def add_header_1(text):
    return doc.add_heading(text, level=1)

def add_header_2(text):
    return doc.add_heading(text, level=2)

# Contadores de IDs
est_id_counter = 1
prac_id_counter = 1
txt_id_counter = 1
frac_id_counter = 1
func_id_counter = 1
