    for r in p_h.runs:
        r.font.size = Pt(12)
        r.font.color.rgb = RGBColor(0x1A, 0x0A, 0x2E)
    
    p_d = doc.add_paragraph()
    p_d.add_run('• Objetivo del Taller: ').bold = True
