        r_h2.bold = True
        r_h2.font.color.rgb = RGBColor(0xB2, 0x22, 0x22)
        r_t2 = p_g2.add_run(f'"{p2}"')
        r_t2.bold = True
        r_t2.font.color.rgb = RGBColor(0x8B, 0x00, 0x00)
        
