def add_texto_item(num_str, title, desc, prompt_text, tips_custom=None):
    global txt_id_counter
    id_code = f"[TXT-{txt_id_counter:03d}]"
    txt_id_counter += 1
    
    tips_val = tips_custom if tips_custom is not None else "👉 Reto Práctico en Casa o en Clase: Copia este prompt en Gemini y personalízalo cambiando los datos, el producto o tus preferencias personales. ¡Observa cómo la IA adapta su respuesta exactamente a lo que le pidas!"
    
    classroom_export_items.append({
        'block_dir': '01. [TXT] BLOQUE_1_PROMPTS_DE_COMUNICACION_Y_TEXTO',
        'block_name': 'BLOQUE III: COMUNICACIÓN, SALUD Y GESTIÓN EN TEXTO',
        'id_code': id_code,
        'title': title,
        'concept': desc,
        'prompt': prompt_text,
        'tips': tips_val,
        'extra': None
    })
    
    p_h = doc.add_heading(f'{num_str} {id_code} {title}', level=3)
    for r in p_h.runs:
        r.font.size = Pt(12)
        r.font.color.rgb = RGBColor(0x1A, 0x0A, 0x2E)
        
    p_d = doc.add_paragraph()
    p_d.add_run('• Objetivo Pedagógico: ').bold = True
    p_d.add_run(desc)
    
    p_g = doc.add_paragraph()
    r_hg = p_g.add_run('• 💬 Prompt / Orden de Texto listo para pegar en Gemini: ')
    r_hg.bold = True
    
    if isinstance(prompt_text, list):
        for s_item in prompt_text:
            if isinstance(s_item, tuple) and len(s_item) == 2:
                s_title, s_prompt = s_item
                p_sub = doc.add_paragraph()
                r_t = p_sub.add_run(f'  [{s_title}]:\n')
                r_t.bold = True
                r_t.font.color.rgb = RGBColor(0x1A, 0x0A, 0x2E)
                r_p = p_sub.add_run(f'"{s_prompt}"')
                r_p.bold = True
                r_p.font.color.rgb = RGBColor(0x00, 0x5A, 0x9E)
            else:
                p_sub = doc.add_paragraph()
                r_p = p_sub.add_run(f'  • "{s_item}"')
                r_p.bold = True
                r_p.font.color.rgb = RGBColor(0x00, 0x5A, 0x9E)
    else:
        r_gt = p_g.add_run(f'"{prompt_text}"')
        r_gt.bold = True
        r_gt.font.color.rgb = RGBColor(0x00, 0x5A, 0x9E)
    doc.add_paragraph()

