def add_fut_item(num_str, title, desc, prompt_gemini):
    global fut_id_counter
    id_code = f"[FUT-{fut_id_counter:03d}]"
    fut_id_counter += 1
    
    clausula_esp = " (REGLA DE ORO DE IDIOMA PARA LA IA: Es absolutamente obligatorio que todo título, texto, rótulo, leyenda, año o etiqueta explicativa que aparezca dibujada dentro de la imagen o infografía generada esté ESCRITO EXCLUSIVAMENTE Y PERFECTAMENTE EN ESPAÑOL CASTELLANO, con ortografía intachable. Bajo ningún concepto generes ningún texto, palabra ni leyenda visual en inglés ni en otros idiomas.)"
    if "REGLA DE ORO DE IDIOMA" not in prompt_gemini:
        prompt_gemini = prompt_gemini.strip() + clausula_esp
    
    classroom_export_items.append({
        'block_dir': '06. [FUT] BLOQUE_6_INFOGRAFIAS_DEL_FUTURO_SCI_FI',
        'block_name': 'BLOQUE VII: LÍNEA DE TIEMPO DEL FUTURO Y SCI-FI (@N.AG.A)',
        'id_code': id_code,
        'title': title,
        'concept': desc,
        'prompt': prompt_gemini,
        'tips': "👉 Ahora te toca a ti: ¡Haz tú una modificación que se te ocurra y sorpréndenos!",
        'extra': None
    })
    
    p_h = doc.add_heading(f'{num_str} {id_code} {title}', level=3)
    for r in p_h.runs:
        r.font.size = Pt(12)
        r.font.color.rgb = RGBColor(0x4A, 0x15, 0x4B)
        
    p_d = doc.add_paragraph()
    p_d.add_run('• Contexto y Proyección Científica: ').bold = True
    p_d.add_run(desc)
    
    p_g = doc.add_paragraph()
