add_header_1("VI. INTRODUCCIÓN A LOS FRACTALES CON IA — FICHAS DIDÁCTICAS Y VÍDEOS MP4 PRE-CONSTRUIDOS")

p_def_f = doc.add_paragraph()
r_t_f = p_def_f.add_run("¿QUÉ ES UN FRACTAL? (Explicación sencilla para el aula):\n")
r_t_f.bold = True
r_t_f.font.size = Pt(12)
r_t_f.font.color.rgb = RGBColor(0x0D, 0x1B, 0x4A)

r_d_f = p_def_f.add_run(
    "Un fractal es una forma geométrica fascinante que se repite a sí misma a diferentes tamaños. "
    "Imagina que coges la rama de un árbol y la miras de cerca: verás que esa rama se divide en ramitas más pequeñas que tienen exactamente la misma forma que el árbol completo. "
    "Y si miras una de esas ramitas con una lupa, verás que vuelve a dividirse de la misma manera una y otra vez, hasta el infinito. "
    "Esta propiedad se llama autosimilitud (ser igual a uno mismo a cualquier escala).\n\n"
    "A diferencia de las figuras geométricas básicas del colegio (como los círculos, triángulos o cuadrados perfectos), los fractales son la geometría que utiliza la Naturaleza para construir la realidad. "
    "Nuestro propio cuerpo y el mundo cotidiano están hechos de fractales: la forma en que se ramifican nuestros pulmones y bronquios para respirar, los vasos sanguíneos, los copos de nieve, las nubes del cielo, las cuencas de los ríos, las costas oceánicas o incluso el brócoli y la coliflor que compramos en la verdulería.\n\n"
    "Gracias a los ordenadores modernos y la Inteligencia Artificial, hoy podemos convertir las fórmulas matemáticas de estos patrones naturales en animaciones y obras de arte visuales extraordinarias."
)
r_d_f.font.size = Pt(11)
r_d_f.font.color.rgb = RGBColor(0x22, 0x22, 0x22)

p_intro_b6 = doc.add_paragraph()
p_intro_b6.add_run("NOTA PEDAGÓGICA CLAVE PARA EL PROFESOR (MAYORES 60+):\nUn fractal o sistema algorítmico complejo puede llegar a consumir horas de cálculo computacional o renderizado para construirse. Por tanto, en clase NO se generan fractales mediante prompts en vivo. En su lugar, el profesor cuenta en la carpeta `CURSO-FRACTALES-FUNCIONES/FRACTALES` con el repertorio maestro pre-construido de 74 Fichas Didácticas en PDF y sus correspondientes animaciones en vídeo MP4. Cuando en la sesión toque un fractal, se proyecta la ficha y el MP4 en pantalla para el deleite, admiración y comprensión intuitiva del alumnado ('Beethoven era sordo y el ordenador ejecuta la partitura visual'). Todos están etiquetados en Título 3 con ID `[FRAC-xxx]` para el Índice y Mapa Mental:")
p_intro_b6.runs[0].italic = True
p_intro_b6.runs[0].font.color.rgb = RGBColor(0x33, 0x33, 0x33)

doc.add_paragraph('----------------------------------------------------------------------------------------------------')

def add_ficha_didactica(num_str, id_code, title, desc, carpeta, sub_dir="FRACTALES"):
    # Check physical folder
    base_path = '/Users/externo/Library/Mobile Documents/com~apple~CloudDocs/PERSONAL/CLASES DE TECNOLOGÍA/CURSO-FRACTALES-FUNCIONES'
    full_dir = os.path.join(base_path, sub_dir, carpeta)
    if not os.path.exists(full_dir):
        full_dir2 = os.path.join(base_path, 'FUNCIONES', carpeta)
        if os.path.exists(full_dir2):
            full_dir = full_dir2
            sub_dir = 'FUNCIONES'
    
    mp4_files = []
    pdf_files = []
    if os.path.exists(full_dir) and not ('NO.' in full_dir or 'NO ' in full_dir):
        for fname in sorted(os.listdir(full_dir)):
            if not ('NO.' in fname or 'NO ' in fname or fname.startswith('._')):
                if fname.lower().endswith('.mp4'):
                    mp4_files.append(fname)
                elif fname.lower().endswith('.pdf'):
                    pdf_files.append(fname)
                    
    extra_str = f"📁 Carpeta: {sub_dir}/{carpeta}\n🎬 Vídeo MP4: {', '.join(mp4_files) if mp4_files else 'Ver carpeta'}\n📄 PDF original: {', '.join(pdf_files) if pdf_files else 'Ver carpeta'}"
    block_d = '04. [FRAC] BLOQUE_4_CATALOGO_DE_FRACTALES_EN_IA' if 'FRAC' in id_code else '04. [FUNC] BLOQUE_4B_CATALOGO_DE_FUNCIONES_3D_EN_IA'
    block_n = 'BLOQUE IV: CATÁLOGO DE FRACTALES EN IA' if 'FRAC' in id_code else 'BLOQUE V: CATÁLOGO DE FUNCIONES 3D EN IA'
    
    classroom_export_items.append({
        'block_dir': block_d,
        'block_name': block_n,
        'id_code': id_code,
        'title': title,
        'concept': desc,
        'prompt': None,
        'tips': "Proyectar la Ficha Didáctica PDF adjunta y reproducir la animación MP4 para mostrar el comportamiento y autosimilitud matemática en clase.",
        'extra': extra_str
    })
    
    p_h = doc.add_heading(f'{num_str} {id_code} {title}', level=3)
    for r in p_h.runs:
        r.font.size = Pt(11.5)
        r.font.color.rgb = RGBColor(0x1A, 0x0A, 0x2E)
    
    p_d = doc.add_paragraph()
    p_d.add_run('• Concepto Matemático / Visual: ').bold = True
    p_d.add_run(desc)
    
    p_f = doc.add_paragraph()
    r_fh = p_f.add_run('• 📁 Carpeta en iCloud: ')
    r_fh.bold = True
    r_fh.font.color.rgb = RGBColor(0x00, 0x5A, 0x9E)
    r_ft = p_f.add_run(f'{sub_dir}/{carpeta}\n')
    r_ft.italic = True
    r_ft.font.color.rgb = RGBColor(0x44, 0x44, 0x44)
    
    if mp4_files:
        r_mp4_h = p_f.add_run('  🎬 Vídeo MP4 para clase: ')
        r_mp4_h.bold = True
        r_mp4_h.font.color.rgb = RGBColor(0x8B, 0x00, 0x00)
        p_f.add_run(f'{", ".join(mp4_files)}\n')
    if pdf_files:
        r_pdf_h = p_f.add_run('  📄 Ficha PDF para alumnos: ')
        r_pdf_h.bold = True
        r_pdf_h.font.color.rgb = RGBColor(0x00, 0x64, 0x00)
        p_f.add_run(f'{", ".join(pdf_files)}')
    doc.add_paragraph()

add_header_2("6.1. Tiempo de Escape (Mandelbrot, Julia, Newton y Buddhabrot)")
add_ficha_didactica("6.1.1.", "[FRAC-001]", "Mandelbrot Feigenbaum", "Ecuación cuadrática Z² + C y la constante de bifurcación universal de Feigenbaum.", "1. TIEMPO_DE_ESCAPE/01_Mandelbrot_Feigenbaum")
add_ficha_didactica("6.1.2.", "[FRAC-002]", "Mandelbrot Valle de los Caballitos de Mar", "Espirales hipnóticas entrelazadas en la frontera del conjunto de Mandelbrot.", "1. TIEMPO_DE_ESCAPE/02_Mandelbrot_Valle_Caballitos")
add_ficha_didactica("6.1.3.", "[FRAC-003]", "Mandelbrot Satélites y Mini-Mandelbrots", "Autosimilitud pura: copias exactas diminutas del conjunto original ocultas en sus ramificaciones.", "1. TIEMPO_DE_ESCAPE/03_Mandelbrot_Satelites")
add_ficha_didactica("6.1.4.", "[FRAC-004]", "Punto de Misiurewicz", "Puntos pre-periódicos donde las espirales se abren en estructuras dendríticas infinitas.", "1. TIEMPO_DE_ESCAPE/04_Mandelbrot_Misiurewicz")
add_ficha_didactica("6.1.5.", "[FRAC-005]", "Barco en Llamas (Burning Ship)", "Variación geométrica tomando el valor absoluto de las partes real e imaginaria antes de elevar al cuadrado.", "1. TIEMPO_DE_ESCAPE/05_Burning_Ship")
add_ficha_didactica("6.1.6.", "[FRAC-006]", "Conjunto de Julia: Conejo de Douady", "Fractal polinómico con simetría ternaria y lóbulos conectados que recuerdan a las orejas de un conejo.", "1. TIEMPO_DE_ESCAPE/06_Julia_Conejo_Douady")
add_ficha_didactica("6.1.7.", "[FRAC-007]", "Conjunto de Julia: Dendrita", "Estructura ramificada en forma de árbol infinito cuando el parámetro C está en el borde del conjunto.", "1. TIEMPO_DE_ESCAPE/07_Julia_Dendrita")
add_ficha_didactica("6.1.8.", "[FRAC-008]", "Conjunto de Julia Cúbico (Z³ + C)", "Iteración polinómica de tercer grado que genera simetrías trilobuladas y estrellas matemáticas.", "1. TIEMPO_DE_ESCAPE/08_Julia_Z3")
add_ficha_didactica("6.1.9.", "[FRAC-009]", "Conjunto de Julia Exponencial de Z³", "Fusión de funciones exponenciales y cúbicas con dinámicas caóticas de escape rápido.", "1. TIEMPO_DE_ESCAPE/09_Julia_ExpZ3")
add_ficha_didactica("6.1.10.", "[FRAC-010]", "Conjunto de Julia Senoidal (Sin Z)", "Comportamiento fractal infinito derivado de la función trigonométrica seno en el plano complejo.", "1. TIEMPO_DE_ESCAPE/10_Julia_Seno")
add_ficha_didactica("6.1.11.", "[FRAC-011]", "Conjunto de Julia Logarítmico", "Estructuras espiraladas generadas por el logaritmo complejo con múltiples ramas.", "1. TIEMPO_DE_ESCAPE/11_Julia_Logaritmico")
add_ficha_didactica("6.1.12.", "[FRAC-012]", "Fractal de Newton Z⁶ - 1 = 0", "Cuencas de atracción al buscar las raíces de un polinomio de grado 6 mediante el método de Newton.", "1. TIEMPO_DE_ESCAPE/12_Newton_Z6")
add_ficha_didactica("6.1.13.", "[FRAC-013]", "Fractal de Newton Z³ - 1 = 0", "La famosa división tricolor del plano que ilustra el caos en la elección de raíces cúbicas de la unidad.", "1. TIEMPO_DE_ESCAPE/13_Newton_Z3")
add_ficha_didactica("6.1.14.", "[FRAC-014]", "El Tricornio (Mandelbar)", "El dual anti-analítico del conjunto de Mandelbrot obtenido usando el conjugado complejo de Z.", "1. TIEMPO_DE_ESCAPE/14_Tricornio")
add_ficha_didactica("6.1.15.", "[FRAC-015]", "Fractal de Lyapunov", "Patrones generados por la estabilidad e inestabilidad de poblaciones modeladas por secuencias ABAB.", "1. TIEMPO_DE_ESCAPE/15_Lyapunov")
add_ficha_didactica("6.1.16.", "[FRAC-016]", "El Buddhabrot", "Representación probabilística de las trayectorias de las órbitas que escapan de Mandelbrot, asemejando a Buda en meditación.", "1. TIEMPO_DE_ESCAPE/16_Buddhabrot")

add_header_2("6.2. Sistemas de Funciones Iteradas (IFS) y Geometría Fractal Clásica")
add_ficha_didactica("6.2.1.", "[FRAC-017]", "Helecho de Barnsley", "Código de 4 transformaciones afines que reproduce milimétricamente la hoja de un helecho natural.", "2. SISTEMAS_IFS/17_Helecho_de_Barnsley")
add_ficha_didactica("6.2.2.", "[FRAC-018]", "Conjunto de Cantor", "El polvo fractal original: eliminar el tercio central de un segmento iterativamente hasta el infinito.", "2. SISTEMAS_IFS/18_Conjunto_de_Cantor")
add_ficha_didactica("6.2.3.", "[FRAC-019]", "Copo de Nieve de Koch", "Curva de perímetro infinito que encierra un área finita, construida añadiendo triángulos equiláteros.", "2. SISTEMAS_IFS/19_Copo_de_Nieve_de_Koch")
add_ficha_didactica("6.2.4.", "[FRAC-020]", "Esponja de Menger", "El análogo 3D de la alfombra de Sierpinski: volumen que tiende a cero mientras su superficie tiende a infinito.", "2. SISTEMAS_IFS/20_Esponja_de_Menger")
add_ficha_didactica("6.2.5.", "[FRAC-021]", "Alfombra de Sierpinski", "Fractal 2D construido subdividiendo un cuadrado en 9 cuadrados menores y eliminando el central.", "2. SISTEMAS_IFS/21_Alfombra_de_Sierpinski")
add_ficha_didactica("6.2.6.", "[FRAC-022]", "Triángulo de Sierpinski", "Estructura geométrica autosimilar construida uniendo los puntos medios de las aristas de un triángulo equilátero.", "2. SISTEMAS_IFS/22_Triangulo_de_Sierpinski")
add_ficha_didactica("6.2.7.", "[FRAC-023]", "Tamiz de Apolonio", "Empaquetado fractal infinito de círculos mutuamente tangentes dentro de un círculo mayor.", "2. SISTEMAS_IFS/23_Tamiz_de_Apolonio")
add_ficha_didactica("6.2.8.", "[FRAC-024]", "Curva de De Rham", "Familia continuada de curvas fractales que generaliza las curvas de Cesàro y Koch.", "2. SISTEMAS_IFS/24_Curva_de_DeRham")
add_ficha_didactica("6.2.9.", "[FRAC-025]", "Isla de Minkowski", "Fractal cuadrático cerrado que genera una silueta irregular que recuerda a una costa o isla dentada.", "2. SISTEMAS_IFS/25_Isla_de_Minkowski")
add_ficha_didactica("6.2.10.", "[FRAC-026]", "Curva del Dragón de Heighway", "Curva obtenida al plegar una tira de papel repetidamente por la mitad y desplegarla en ángulos de 90 grados.", "2. SISTEMAS_IFS/26_Curva_del_Dragon")
add_ficha_didactica("6.2.11.", "[FRAC-027]", "Curva de Hilbert", "Curva que llena el espacio (Space-filling curve) capaz de visitar cada punto de una cuadrícula sin cruzarse.", "2. SISTEMAS_IFS/27_Curva_de_Hilbert")
add_ficha_didactica("6.2.12.", "[FRAC-028]", "Curva C de Lévy", "Curva autosimilar que se asemeja a una filigrana o encaje intrincado, construida con triángulos rectángulos isósceles.", "2. SISTEMAS_IFS/28_Curva_de_Levy")
add_ficha_didactica("6.2.13.", "[FRAC-029]", "T-Cuadrada (T-Square)", "Fractal geométrico de dos dimensiones creado a partir de cuadrados concéntricos reducidos a la mitad en cada vértice.", "2. SISTEMAS_IFS/29_T_Cuadrada")
add_ficha_didactica("6.2.14.", "[FRAC-030]", "Fractal de Vicsek", "Fractal en forma de copo o cruz que surge al subdividir un cuadrado en una cuadrícula de 3x3 y conservar 5 subcuadrados.", "2. SISTEMAS_IFS/30_Fractal_de_Vicsek")
add_ficha_didactica("6.2.15.", "[FRAC-031]", "Estrella de Sierpinski (N-Copo)", "Generalización del triángulo de Sierpinski a polígonos regulares de N lados en forma de estrellas concéntricas.", "2. SISTEMAS_IFS/31_Ncopo_Estrella_Sierpinski")
add_ficha_didactica("6.2.16.", "[FRAC-032]", "Árbol de Pitágoras", "Estructura fractal plana construida a partir de cuadrados y triángulos rectángulos que demuestra visualmente el teorema de Pitágoras.", "2. SISTEMAS_IFS/32_Arbol_de_Pitagoras")

add_header_2("6.3. Sistemas L (Lindenmayer) y Modelado Biológico")
add_ficha_didactica("6.3.1.", "[FRAC-033]", "Curva de Moore", "Variante continua de la curva de Hilbert que forma un bucle cerrado llenando todo el espacio plano.", "3. SISTEMAS_L/33_Curva_de_Moore")
add_ficha_didactica("6.3.2.", "[FRAC-034]", "Curva de Peano", "La primera curva descubierta capaz de recubrir densamente todos los puntos del plano.", "3. SISTEMAS_L/34_Curva_de_Peano")
add_ficha_didactica("6.3.3.", "[FRAC-035]", "Curva de Gosper (Flowsnake)", "Curva fractal construida a partir de teselaciones hexagonales del plano con forma de serpiente infinita.", "3. SISTEMAS_L/35_Curva_de_Gosper")
add_ficha_didactica("6.3.4.", "[FRAC-036]", "Dosel Fractal (Fractal Canopy)", "Modelado algorítmico de la ramificación de los árboles, donde cada rama se divide en dos ramas menores en ángulo constante.", "3. SISTEMAS_L/36_Dosel_Fractal")
add_ficha_didactica("6.3.5.", "[FRAC-037]", "Corales y Arrecifes por Sistemas L", "Simulación del crecimiento orgánico de colonias de coral marino mediante reglas gramaticales de Lindenmayer.", "3. SISTEMAS_L/37_Corales_Sistema_L")
add_ficha_didactica("6.3.6.", "[FRAC-038]", "Redes y Mallas por Sistemas L", "Patrones reticulares complejos generados por ramificaciones que se reconectan algorítmicamente.", "3. SISTEMAS_L/38_Redes_Sistema_L")
add_ficha_didactica("6.3.7.", "[FRAC-039]", "Cristales de Nieve por Sistemas L", "Crecimiento hexagonal dendrítico simulando la cristalización del agua en la atmósfera.", "3. SISTEMAS_L/39_Cristales_Sistema_L")
add_ficha_didactica("6.3.8.", "[FRAC-040]", "Palabra y Espiral de Fibonacci", "Patrón espiralado que traduce secuencias binarias de la sucesión de Fibonacci a giros geométricos exactos.", "3. SISTEMAS_L/40_Palabra_de_Fibonacci")

