add_ficha_didactica("6.4.1.", "[FRAC-041]", "Atractor de Aizawa", "Elegante atractor 3D en forma de esfera o tubo con una trayectoria central que atraviesa su eje vertical.", "4. ATRACTORES/41_Atractor_Aizawa")
