add_ficha_didactica("6.4.5.", "[FRAC-045]", "Atractor de Thomas", "Atractor ciclónicamente simétrico en 3D que describe un laberinto caótico en una cuadrícula tridimensional.", "4. ATRACTORES/45_Atractor_Thomas")

