add_ficha_didactica("6.5.1.", "[FRAC-046]", "Giroide (Superficie Minimal Continua)", "Superficie periódica con curvatura media cero que divide el espacio en dos laberintos entrelazados sin tocarse.", "5. FRACTALES_3D/46_Giroide")
add_ficha_didactica("6.5.2.", "[FRAC-047]", "Conjunto de Glynn", "Generalización tridimensional de conjuntos de Julia polinómicos con simetrías sorprendentes.", "5. FRACTALES_3D/47_Conjunto_de_Glynn")
add_ficha_didactica("6.5.3.", "[FRAC-048]", "La Mandelcaja (Mandelbox)", "Fractal en forma de cubo infinito o caja mágica con pliegues esféricos y cúbicos en todas sus caras interiores.", "5. FRACTALES_3D/48_Mandelcaja")
add_ficha_didactica("6.5.4.", "[FRAC-049]", "Mandelbulbo Cúbico (Power 8)", "El santo grial del Mandelbrot 3D verdadero con potencia 8, revelando valles, montañas y cavernas arquitectónicas.", "5. FRACTALES_3D/49_Mandelbulbo_Cubico")
add_ficha_didactica("6.5.5.", "[FRAC-050]", "Mandelbrot Cuaterniónico (4D)", "Sección tridimensional del conjunto de Mandelbrot generalizado en el álgebra de cuaterniones de 4 dimensiones.", "5. FRACTALES_3D/50_Mandelbrot_Cuaternionico")
add_ficha_didactica("6.5.6.", "[FRAC-051]", "Mandelbulbo Clásico", "La primera aproximación exitosa en 3D de las espirales de Mandelbrot mediante coordenadas esféricas trihypercomplejas.", "5. FRACTALES_3D/51_Mandelbulbo_Clasico")

