add_ficha_didactica("6.6.1.", "[FRAC-052]", "Juliabulb Inverso", "Inversión esférica geométrica del conjunto de Julia tridimensional revelando estructuras interiores.", "FRACTALES_ALEATORIOS/52_Juliabulb_Inverso")
add_ficha_didactica("6.6.2.", "[FRAC-053]", "Paradoja de la Costa de Richardson-Mandelbrot", "Demostración de que la longitud de la costa de un país es infinita si se mide con una regla infinitamente pequeña.", "FRACTALES_ALEATORIOS/53_Paradoja_de_la_Costa")

add_header_2("6.7. Módulo Monográfico Didáctico: Los Fractales en la Naturaleza, el Arte y el Cuerpo Humano")
add_ficha_didactica("6.7.1.", "[FRAC-054]", "Los 3 Pilares de los Fractales (Autosimilitud, Iteración y Dimensión No Entera)", "Síntesis pedagógica visual de los tres conceptos que definen la geometría fractal.", "DIDACTICOS/54_ARI_Los_3_Pilares")
add_ficha_didactica("6.7.2.", "[FRAC-055]", "Los Monstruos de las Matemáticas", "La historia de cómo Weierstrass, Cantor y Koch desafiaron la geometría euclidiana con curvas 'imposibles'.", "DIDACTICOS/55_Los_Monstruos_de_las_Matematicas")
add_ficha_didactica("6.7.3.", "[FRAC-056]", "La Gran Ola de Kanagawa de Hokusai", "Análisis fractal del grabado japonés del siglo XIX donde las garras de espuma de la ola repiten la forma de la ola grande.", "DIDACTICOS/56_La_Gran_Ola_Hokusai")
add_ficha_didactica("6.7.4.", "[FRAC-057]", "La Dimensión 1.5 (Entre la Línea y el Plano)", "Explicación intuitiva para mayores de cómo una curva fractal ocupa más que una línea 1D pero menos que un área 2D.", "DIDACTICOS/57_Dimension_1_5")
add_ficha_didactica("6.7.5.", "[FRAC-058]", "Tú eres un Fractal (Pulmones, Bronquios y Sistema Circulatorio)", "Cómo la evolución natural utilizó la geometría fractal para empaquetar 100 metros cuadrados de superficie pulmonar dentro de nuestro pecho.", "DIDACTICOS/58_Tu_Eres_un_Fractal")
add_ficha_didactica("6.7.6.", "[FRAC-059]", "Tu Teléfono Móvil es un Fractal (Antenas de Sierpinski)", "Cómo la antena interior del móvil utiliza el triángulo de Sierpinski para captar frecuencias Bluetooth, Wifi y 5G a la vez.", "DIDACTICOS/59_Tu_Movil_Es_un_Fractal")
add_ficha_didactica("6.7.7.", "[FRAC-060]", "El Fractal Comestible (Brócoli Romanesco y Coliflor)", "La maravilla matemática que podemos tocar y comer en la verdulería: conos espiralados perfectos en proporción áurea.", "DIDACTICOS/60_El_Fractal_Comestible")
add_ficha_didactica("6.7.8.", "[FRAC-061]", "Jackson Pollock y el Action Painting", "El descubrimiento de que las salpicaduras y goteos de pintura del famoso artista moderno tienen una dimensión fractal D = 1.72 exacto.", "DIDACTICOS/61_Jackson_Pollock")
add_ficha_didactica("6.7.9.", "[FRAC-062]", "La Red Cósmica del Universo", "La distribución fractal de supercúmulos de galaxias y filamentos de materia oscura en el cosmos observable.", "DIDACTICOS/62_La_Red_Cosmica")
add_ficha_didactica("6.7.10.", "[FRAC-063]", "El Ruido Rosa y la 1/f (La Música de la Naturaleza)", "El equilibrio fractal auditivo entre el caos del ruido blanco y la monotonía del sonido constante, presente en el viento y las olas.", "DIDACTICOS/63_Ruido_Rosa")
add_ficha_didactica("6.7.11.", "[FRAC-064]", "Los Templos Hindúes y la Arquitectura Védica", "Torres sagradas hindúes (Shikhara) compuestas por repeticiones autosimilares de torres más pequeñas que simbolizan la montaña cósmica.", "DIDACTICOS/64_Templos_Indues")
add_ficha_didactica("6.7.12.", "[FRAC-065]", "El Ritmo Fractal del Corazón Sano", "El electrocardiograma normal muestra variabilidad fractal en los latidos; la pérdida de variabilidad fractal avisa de arritmias.", "DIDACTICOS/65_Ritmo_Fractal_Corazon")
add_ficha_didactica("6.7.13.", "[FRAC-066]", "Figuras de Lichtenberg (Rayos y Descargas Eléctricas)", "Las hermosas marcas dendríticas que deja un rayo al atravesar un aislante de metacrilato o la piel humana.", "DIDACTICOS/66_Figuras_de_Lichtenberg")
add_ficha_didactica("6.7.14.", "[FRAC-067]", "La Economía es Rugosa (Los Mercados Financieros)", "Cómo Benoît Mandelbrot demostró que las caídas de la Bolsa no siguen una campana de Gauss suave, sino saltos fractales abruptos.", "DIDACTICOS/67_La_Economia_Es_Rugosa")
add_ficha_didactica("6.7.15.", "[FRAC-068]", "África y la Arquitectura en Código Binario", "Las aldeas tradicionales africanas (Ba-Ila, Camerún) organizadas en círculos de círculos de casas con estructura fractal.", "DIDACTICOS/68_Africa_Codigo_Binario")
add_ficha_didactica("6.7.16.", "[FRAC-069]", "El Cristal de Bismuto", "Cristal metálico iridiscente que crece en escaleras piramidales fractales en ángulo recto debido a la velocidad diferencial de enfriamiento.", "DIDACTICOS/69_El_Bismuto")
add_ficha_didactica("6.7.17.", "[FRAC-070]", "El Ojo de la Tormenta y los Huracanes", "Espirales fractales de nubes en la atmósfera terrestre y en la Gran Mancha Roja de Júpiter.", "DIDACTICOS/70_Ojo_de_la_Tormenta")
add_ficha_didactica("6.7.18.", "[FRAC-071]", "El Efecto Droste (La Imagen dentro de la Imagen)", "La recursividad visual clásica del envase de cacao Droste donde una enfermera sostiene una bandeja con el mismo envase infinito.", "DIDACTICOS/71_Efecto_Droste")
add_ficha_didactica("6.7.19.", "[FRAC-072]", "Cuencas Fluviales y Redes Hidrográficas", "Cómo el Amazonas y todos los grandes ríos del mundo dividen sus afluentes con exactamente el mismo árbol fractal algorítmico.", "DIDACTICOS/72_Cuencas_Fluviales")
add_ficha_didactica("6.7.20.", "[FRAC-073]", "J.S. Bach y las Fugas Fractales", "La estructura matemática recursiva en el 'Arte de la Fuga' y el canon del cangrejo del genial compositor alemán.", "DIDACTICOS/73_Bach_Fractales")
add_ficha_didactica("6.7.21.", "[FRAC-074]", "Philip Glass y el Minimalismo Repetitivo", "Patrones rítmicos modulares que se expanden y contraen en estructuras autosimilares en la música contemporánea.", "DIDACTICOS/74_Philip_Glass")

