add_header_1("VII. INTRODUCCIÓN A LAS FUNCIONES Y SUPERFICIES EN 3D CON IA — FICHAS Y VÍDEOS PRE-CONSTRUIDOS")

p_def_func = doc.add_paragraph()
r_t_func = p_def_func.add_run("¿QUÉ ES UNA FUNCIÓN O SUPERFICIE EN 3D? (Explicación sencilla para el aula):\n")
r_t_func.bold = True
r_t_func.font.size = Pt(12)
r_t_func.font.color.rgb = RGBColor(0x0D, 0x1B, 0x4A)

r_d_func = p_def_func.add_run(
    "Una función matemática en 3D es como un 'plano o receta de arquitectura' para moldear el espacio. "
    "Imagina una sábana de tela plana extendida sobre una mesa lisa. "
    "Si le aplicamos una regla o fórmula matemática (por ejemplo, 'donde haya una curva, levanta la tela suavemente como una ola del mar o dóblala en forma de silla de montar'), "
    "esa superficie plana se transforma inmediatamente en una escultura tridimensional llena de volúmenes, pliegues, cúpulas y valles (z = f(x, y)).\n\n"
    "Aunque la expresión 'función matemática' pueda sonar técnica, en realidad vivimos rodeados cotidianamente de estas superficies: "
    "la curva parabólica de la antena parabólica o del faro de un coche diseñada para enfocar la luz, la acústica en forma de concha de un auditorio de música, o los impresionantes techos ondulados que construía el genial arquitecto Antoni Gaudí en sus edificios.\n\n"
    "En este módulo exploramos cómo el ordenador transforma esas 'fórmulas receta' en asombrosos paisajes tridimensionales y estructuras arquitectónicas del futuro, demostrando a los alumnos que las matemáticas son un lenguaje lleno de belleza y utilidad práctica."
)
r_d_func.font.size = Pt(11)
r_d_func.font.color.rgb = RGBColor(0x22, 0x22, 0x22)

p_intro_b7 = doc.add_paragraph()
p_intro_b7.add_run("NOTA PEDAGÓGICA CLAVE PARA EL PROFESOR (MAYORES 60+):\nAl igual que con los fractales, las funciones matemáticas y superficies tridimensionales (`z = f(x, y)`) ya están pre-construidas por el profesor en la carpeta `CURSO-FRACTALES-FUNCIONES/FUNCIONES`. En clase se proyectan las 42 Fichas Didácticas en PDF y sus animaciones en MP4 para que los alumnos entiendan intuitivamente cómo una fórmula algebraica se transforma en la arquitectura del futuro (como las cubiertas de Antoni Gaudí o Zaha Hadid). Todos numerados con ID `[FUNC-xxx]` en Título 3:")
p_intro_b7.runs[0].italic = True
p_intro_b7.runs[0].font.color.rgb = RGBColor(0x33, 0x33, 0x33)

doc.add_paragraph('----------------------------------------------------------------------------------------------------')

add_header_2("7.1. Funciones Elementales, Álgebra Básica y Trigonometría del Plano")
add_ficha_didactica("7.1.1.", "[FUNC-001]", "Función Constante (f(x) = k)", "La línea horizontal inmutable que mantiene la misma altura para cualquier valor del plano.", "FUNCION_0001_Constante", "FUNCIONES")
add_ficha_didactica("7.1.2.", "[FUNC-002]", "Función Lineal (f(x) = x)", "La recta diagonal de pendiente 45 grados que representa el equilibrio y la proporcionalidad directa.", "FUNCION_0002_Lineal_x", "FUNCIONES")
add_ficha_didactica("7.1.3.", "[FUNC-003]", "Función Afín (f(x) = mx + n)", "La recta desplazada con pendiente y ordenada en el origen, base del cálculo comercial diario.", "FUNCION_0003_Afin", "FUNCIONES")
add_ficha_didactica("7.1.4.", "[FUNC-004]", "Función Cuadrática (Parábola x²)", "La parábola clásica en forma de U que rige el tiro parabólico, los faros de los coches y las antenas parabólicas.", "FUNCION_0004_Cuadratica_X_cuadrado", "FUNCIONES")
add_ficha_didactica("7.1.5.", "[FUNC-005]", "Función Cúbica (Polinomio x³)", "La curva en forma de S o punto de inflexión que modela crecimientos acelerados y cambios de volumen.", "FUNCION_0005_Cubica_x_cubo", "FUNCIONES")
add_ficha_didactica("7.1.6.", "[FUNC-006]", "Función Racional Hipérbola (1/x)", "La curva asintótica que nunca toca los ejes, representando relaciones inversamente proporcionales.", "FUNCION_0007_Racional_1_entre_x", "FUNCIONES")
add_ficha_didactica("7.1.7.", "[FUNC-007]", "Función Raíz Cuadrada (√x)", "La media parábola horizontal que modela el crecimiento suave y amortiguado en la naturaleza.", "FUNCION_0008_sqrt_x", "FUNCIONES")
add_ficha_didactica("7.1.8.", "[FUNC-008]", "Función Raíz Cúbica (∛x)", "La curva simétrica continua que atraviesa el origen cruzando los cuatro cuadrantes del plano.", "FUNCION_0009_sqrt_cubica_x", "FUNCIONES")
add_ficha_didactica("7.1.9.", "[FUNC-009]", "Función Valor Absoluto (|x|)", "El vértice en V perfecta de 90 grados que mide distancias puras sin números negativos.", "FUNCION_0010_abs_x", "FUNCIONES")
add_ficha_didactica("7.1.10.", "[FUNC-010]", "Función Exponencial (eˣ)", "La curva del crecimiento explosivo, el interés compuesto de los bancos y la reproducción biológica.", "FUNCION_0011_exp_x", "FUNCIONES")
add_ficha_didactica("7.1.11.", "[FUNC-011]", "Polinomio de 2º Grado (2x² + 4x - 5)", "Parábola desplazada con vértices y raíces exactas que ilustra la resolución de ecuaciones de segundo grado.", "FUNCION_0012_2x_cuadrado_mas_4x_menos_5", "FUNCIONES")
add_ficha_didactica("7.1.12.", "[FUNC-012]", "Logaritmo Neperiano (ln x)", "La curva inversa de la exponencial que modela cómo los humanos percibimos el sonido (decibelios) y la luz.", "FUNCION_0013_ln_x", "FUNCIONES")
add_ficha_didactica("7.1.13.", "[FUNC-013]", "Función Signo (sign x)", "La función escalón que salta instantáneamente de -1 a +1 al cruzar el origen cero.", "FUNCION_0014_sign_x", "FUNCIONES")
add_ficha_didactica("7.1.14.", "[FUNC-014]", "Función Seno (sen x)", "La onda sinusoidal pura y armónica que describe las olas del mar, el sonido y la corriente alterna de casa.", "FUNCION_0020_sen_x", "FUNCIONES")
add_ficha_didactica("7.1.15.", "[FUNC-015]", "Función Coseno (cos x)", "La onda sinusoidal desplazada en fase 90 grados, gemela inseparable del seno en toda vibración física.", "FUNCION_0021_cos_x", "FUNCIONES")
add_ficha_didactica("7.1.16.", "[FUNC-016]", "Función Tangente (tan x)", "La curva con asíntotas verticales infinitas que mide pendientes y ángulos de inclinación arquitectónica.", "FUNCION_0022_tan_x", "FUNCIONES")
add_ficha_didactica("7.1.17.", "[FUNC-017]", "Función Cotangente (cot x)", "La onda inversa trigonométrica con asíntotas en los múltiplos de pi.", "FUNCION_0023_cot_x", "FUNCIONES")
add_ficha_didactica("7.1.18.", "[FUNC-018]", "Función Secante (sec x)", "La sucesión de parábolas abiertas hacia arriba y abajo separadas por el vacío asintótico.", "FUNCION_0024_sec_x", "FUNCIONES")
add_ficha_didactica("7.1.19.", "[FUNC-019]", "Función Cosecante (csc x)", "La recíproca trigonométrica del seno que completa las 6 funciones fundamentales de la trigonometría.", "FUNCION_0025_csc_x", "FUNCIONES")

add_header_2("7.2. Curvas Polares 2D y Superficies Paramétricas en 3D")
add_ficha_didactica("7.2.1.", "[FUNC-020]", "La Rosácea Polar (Rosacea)", "Curva en coordenadas polares (`r = a cos kθ`) que dibuja flores geométricas perfectas de 4 u 8 pétalos.", "FUNCION_0100_Rosacea", "FUNCIONES")
add_ficha_didactica("7.2.2.", "[FUNC-021]", "Espiral Logarítmica (`r = a e^(bθ)`)", "La espiral geométrica del caracol Nautilus, los huracanes y las galaxias espaciales del universo.", "FUNCION_0101_Espiral_Logaritmica", "FUNCIONES")
add_ficha_didactica("7.2.3.", "[FUNC-022]", "Caracol de Pascal (Limaçon)", "Curva epicicloide con o sin lazo interior, estudiada por Étienne Pascal en el siglo XVII.", "FUNCION_0102_Caracol_de_Pascal", "FUNCIONES")
add_ficha_didactica("7.2.4.", "[FUNC-023]", "La Cardioide (Corazón Polar)", "El caso especial del caracol de Pascal con forma de corazón perfecto, caustica de luz en una taza de café.", "FUNCION_0103_Cardioide", "FUNCIONES")
add_ficha_didactica("7.2.5.", "[FUNC-024]", "Espiral de Arquímedes (`r = a + bθ`)", "La espiral con separación constante entre sus brazos, utilizada en muelles de relojería y bobinas de rollo.", "FUNCION_0104_Espiral_de_Arquimedes", "FUNCIONES")
add_ficha_didactica("7.2.6.", "[FUNC-025]", "Ondas Cruzadas (`z = sin x + sin y`)", "Superficie tridimensional suave en forma de huevera o dunas armónicas que se cruzan en ángulos rectos.", "FUNCION_0106_sin_x_mas_sin_y", "FUNCIONES")
add_ficha_didactica("7.2.7.", "[FUNC-026]", "Superficie `z = sec x + csc x`", "Paisaje espacial de torres asintóticas y valles profundos generados por la suma de inversas trigonométricas.", "FUNCION_0107_sec_x_mas_csc_x", "FUNCIONES")
add_ficha_didactica("7.2.8.", "[FUNC-028]", "Superficie `z = tan x + cot x`", "Compleja rejilla tridimensional de acantilados verticales y saltos trigonométricos.", "FUNCION_0108_tan_x_mas_cot_x", "FUNCIONES")
add_ficha_didactica("7.2.9.", "[FUNC-029]", "Ondas Cosenoidales (`z = cos x + cos y`)", "El paisaje de colinas y depresiones suaves desplazadas medio ciclo respecto al seno.", "FUNCION_0109_cos_x_mas_cos_y", "FUNCIONES")
add_ficha_didactica("7.2.10.", "[FUNC-030]", "Paraboloide Circular (`z = x² + y²`)", "El cuenco parabólico tridimensional en forma de copa del que beben las antenas de satélite del mundo.", "FUNCION_0110_x_cuadrado_mas_y_cuadrado", "FUNCIONES")
add_ficha_didactica("7.2.11.", "[FUNC-031]", "Superficie Ondulada `z = 3 sin(0.2θ)`", "Superficie de revolución suave con ondulaciones radiales en torno al eje central z.", "FUNCION_0112_z_igual_3sin_0_2theta", "FUNCIONES")
add_ficha_didactica("7.2.12.", "[FUNC-032]", "Superficie `z = sin(2θ)`", "Modulación angular de segundo armónico en el espacio tridimensional con dos crestas y dos valles.", "FUNCION_0113_z_igual_sin_2theta", "FUNCIONES")
add_ficha_didactica("7.2.13.", "[FUNC-033]", "Superficie `z = sin(3θ)`", "Modulación tridimensional de simetría ternaria semejante a una hélice de tres palas.", "FUNCION_0114_z_igual_sin_3theta", "FUNCIONES")
add_ficha_didactica("7.2.14.", "[FUNC-034]", "Ondas Complejas `z = 4 + 2 sin(6-10θ)`", "Estructura acanalada de alta frecuencia angular girando alrededor del cilindro central.", "FUNCION_0115_z_igual_4_mas_2sin6_10theta", "FUNCIONES")
add_ficha_didactica("7.2.15.", "[FUNC-035]", "Paraboloide Hiperbólico (`z = x² - y²`) — La Silla de Montar de Gaudí", "La famosa superficie doblemente reglada de curvatura gaussiana negativa, cumbre de la arquitectura de Félix Candela y Gaudí.", "FUNCION_0116_z_igual_x_cuadrado_menos_y_cuadrado", "FUNCIONES")
add_ficha_didactica("7.2.16.", "[FUNC-036]", "Superficie Mixta (`z = -x + sin(10x)`)", "Combinación de una pendiente inclinada lineal con una vibración sinusoidal de alta frecuencia.", "FUNCION_0117_z_igual_menos_x_mas_sin_10x", "FUNCIONES")

add_header_2("7.3. Superficies Complejas, Topología Espacial y Atractores del Caos")
add_ficha_didactica("7.3.1.", "[FUNC-037]", "Mapas de Contorno y Curvas de Nivel (Contour)", "Cómo un mapa topográfico 2D de líneas altimétricas representa con exactitud las montañas de una superficie 3D.", "FUNCION_0200_Contour", "FUNCIONES")
add_ficha_didactica("7.3.2.", "[FUNC-038]", "El Toroide o Donut Espacial (Toroid)", "Superficie de revolución en forma de rosquilla, fundamental en geometría de campos magnéticos y reactores Tokamak.", "FUNCION_0201_Toroid", "FUNCIONES")
add_ficha_didactica("7.3.3.", "[FUNC-039]", "Campos Vectoriales 3D (Vector Field)", "Representación visual de fuerzas físicas (viento, gravedad, corrientes marinas) indicando magnitud y dirección en cada punto del espacio.", "FUNCION_0202_Campo_Vectorial", "FUNCIONES")
add_ficha_didactica("7.3.4.", "[FUNC-040]", "La Concoide de Nicomedes (Conchoid)", "Curva algebraica del siglo II a.C. inventada para resolver el problema clásico de la trisección de un ángulo.", "FUNCION_0203_Conchoid", "FUNCIONES")
add_ficha_didactica("7.3.5.", "[FUNC-041]", "Primitivas Topológicas (Primitives)", "Los volúmenes elementales puros de la geometría 3D: esfera, cubo, cilindro, cono y pirámide de los que nace todo diseño.", "FUNCION_0204_Primitives", "FUNCIONES")
add_ficha_didactica("7.3.6.", "[FUNC-042]", "Torus Knot (El Nudo de Trébol en Toroide)", "Curva matemática cerrada y continua que se enrolla P veces alrededor de un toroide sin cortarse ni tener principio ni fin.", "FUNCION_0205_Torus_Knot", "FUNCIONES")
add_ficha_didactica("7.3.7.", "[FUNC-043]", "Atractor de Lorenz (El Caos y el Efecto Mariposa)", "La órbita caótica en dos bucles (`dx/dt = σ(y-x)...`) que Edward Lorenz descubrió en 1963 cambiando la ciencia del clima para siempre.", "FUNCION_0206_Lorenz_Attractor", "FUNCIONES")

# ==============================================================================
# BLOQUE 6: MUNDO POR DENTRO E INGENIERÍA / RECONSTRUCCIÓN HISTÓRICA [INT]
# ==============================================================================
add_header_1("VI. MUNDO POR DENTRO E INGENIERÍA / RECONSTRUCCIÓN HISTÓRICA (CATÁLOGO [INT] — 60 SESIONES)")

add_header_2("6.1. Maravillas de la Antigüedad y Arquitectura Clásica")
add_int_item("6.1.1.", "La Gran Biblioteca de Alejandría reconstruida por dentro", 
             "Reconstrucción fidedigna de las salas de lectura renacentistas e infinidad de papiros en estantes de madera de cedro bajo la luz de lucernarios de alabastro.",
             "Infografía 3D de corte arquitectónico hiperrealista que muestre el interior de la Gran Biblioteca de Alejandría en su apogeo del siglo III a.C., con sabios conversando entre galerías de columnas helenísticas de mármol e interminables estanterías repletas de rollos de papiro iluminados por rayos de sol dorados.")

add_int_item("6.1.2.", "Corte transversal de un cohete interplanetario Starship con sus tanques de metano", 
             "La nave espacial reutilizable más grande de la historia (121 metros de altura en total): cuerpo de acero inoxidable, tanques de oxígeno líquido superenfriado y motores Raptor disparando llama azul.",
             "Infografía en corte longitudinal 3D de la nave interplanetaria de segunda etapa Starship posada en la plataforma de lanzamiento bajo la luz de las estrellas, mostrando la cúpula superior de carga útil o zona habitable para 100 personas con cubiertas giratorias e invernaderos de microgravedad, los dos inmensos tanques cilíndricos interiores de acero inoxidable 304L llenos de metano líquido (CH4) e sub-enfriado y oxígeno líquido (LOX) con sus cúpulas difusoras, y la base inferior revelando los seis motores Raptor de ciclo de combustión escalonada de metano listos para encenderse con un fulgor violeta y azul.")

add_int_item("6.1.3.", "El interior de un hormiguero subterráneo por dentro: cámaras, reina y túneles", 
             "La asombrosa arquitectura social y biológica de las hormigas bajo tierra: cámaras de cría, despensas de semillas, granjas de hongos y ventilación.",
             "Infografía biológica en corte longitudinal 3D de un gran hormiguero subterráneo bajo el césped de un bosque, mostrando en sección transversal la compleja red de túneles y cámaras excavadas en la tierra oscura por miles de hormigas obreras, revelando en detalle la cámara real donde la gran hormiga reina deposita sus huevos rodeada de nodrizas, las salas incubadoras ordenadas por edad desde huevos hasta larvas y pupas blancas, las despensas donde almacenan granos y semillas, las cámaras agrícolas subterráneas donde cultivan hongos sobre hojas masticadas, y los chimeneas de ventilación vertical que mantienen la temperatura constante.")

add_int_item("6.1.4.", "Corte del Transbordador Espacial en órbita con bodega abierta y brazo extendido", 
             "La icónica nave espacial reutilizable de la NASA por dentro: cabina de dos cubiertas para astronautas, bodega de carga con satélite y el brazo mecánico Canadarm en órbita.",
             "Infografía y corte transversal 3D de un Transbordador Espacial de la NASA orbitando en el espacio negro con la curvatura de la Tierra azul al fondo, mostrando en corte el interior de la cabina de tripulación dividida en dos cubiertas con los astronautas en los controles, las grandes compuertas de la bodega de carga completamente abiertas desvelando un satélite de investigación brillante, y el famoso brazo robótico articulado Canadarm extendido en el espacio maniobrando en ingravidez.")

add_int_item("6.1.5.", "El Partenón de Atenas a todo color con la colosal estatua de Atenea", 
             "Cómo era realmente el templo gálico: colores vivos (rojos y azules) en los frisos y la estatua de Atenea Parthenos de 12 metros en oro y marfil.",
             "Infografía 3D del interior de la cella del Partenón en la Acrópolis de Atenas en el año 438 a.C., revelando la verdadera policromía del mármol en tonos rojos, dorados y azules vivos, dominada en el centro por la majestuosa estatua de 12 metros de Atenea Parthenos en oro y marfil resplandeciendo ante un estanque de agua reflectante.")

add_int_item("6.1.6.", "Reconstrucción del Mausoleo de Halicarnaso culminado con cuadriga de mármol", 
             "La tumba monumental que dio nombre a todos los mausoleos del mundo, con 36 columnas jónicas y la estatua ecuestre en su cúspide piramidal escalonada.",
             "Corte 3D arquitectónico del Mausoleo de Halicarnaso en el siglo IV a.C., combinando estilos griego, egipcio y licio, mostrando el podio macizo con estatuas de combate, la columnata central perimetral, la cámara funeraria interior y la pirámide escalonada coronada por una cuadriga colosal de mármol de 6 metros contra un cielo mediterráneo.")

add_int_item("6.1.7.", "El Faro de Alejandría (120 m de altura) con su espejo reflectante de bronce", 
             "El rascacielos del mundo antiguo que guiaba a los barcos a 50 km de distancia mediante un horno de leña continuo magnificado por espejos cóncavos.",
             "Infografía de corte transversal 3D del Faro de Alejandría en el siglo III a.C., mostrando sus tres cuerpos de piedra (cuadrado, octogonal y cilíndrico) ascendiendo 120 metros, la rampa interior de animales de carga subiendo leña, y en el mirador superior, el horno encendido y el gigantesco espejo reflectante de bronce curvo proyectando un haz de luz hacia barcos lejanos en el mar.")

add_int_item("6.1.8.", "El Panteón de Roma por dentro: óculo solar y cúpula de hormigón aligerado", 
             "La cúpula de hormigón no armado más grande jamás construida por el ser humano, con casetones decrecientes y su rayo de luz solar cruzando el templo.",
             "Corte transversal 3D fotorrealista del Panteón de Agripa en Roma al mediodía de equinoccio, mostrando la grandiosa cúpula semiesférica de casetones decrecientes de hormigón de piedra pómez, los muros cilíndricos de 6 metros de grosor con arcos de descarga ocultos, y un impresionante rayo de luz cenital entrando por el óculo de 9 metros e iluminando el suelo de mármol de colores.")

add_int_item("6.1.9.", "Los Baños de Caracalla en Roma: caldarium, piscinas e hipocausto de fuego", 
             "El prodigio termal imperial para 1.600 ciudadanos simultáneos con calefacción por suelo radiante (hipocausto) alimentada por hornos subterráneos de leña.",
             "Infografía 3D de doble nivel de las Termas de Caracalla en Roma, mostrando en la parte superior los suntuosos salones del caldarium cubiertos de mosaicos e inmensas bóvedas con piscinas de vapor, y en el nivel subterráneo, el laberinto de hornos (praefurnia) donde los esclavos alimentaban con leña el sistema de hipocausto que hacía circular aire ardiendo bajo el suelo de ladrillo suspendido.")

add_int_item("6.1.10.", "La mítica Atlántida con sus anillos concéntricos de agua y palacios de bronce", 
             "Reconstrucción arquitectónica de la gran capital marina descrita por Platón en el Critias, con sus tres anillos de canales navegables y murallas revestidas de oricalco.",
             "Reconstrucción en vista aérea isométrica 3D y corte de la legendaria ciudad de la Atlántida en una isla volcánica exuberante, mostrando sus tres anillos concéntricos perfectos de agua y tierra conectados por puentes de piedra, grandes puertos repletos de barcos con velas de púrpura, y en el centro, la Acrópolis real con el Templo de Poseidón fulgurando con revestimientos de plata, oro y oricalco rojo.")

add_int_item("6.1.11.", "La ciudadela inca de Machu Picchu con acueductos en terraza y palacios", 
             "El prodigio de ingeniería antisísmica e hidrológica en las cumbres de los Andes, con canales de agua potable fluyendo por fuentes talladas en granito.",
             "Corte transversal 3D y vista de detalle de Machu Picchu en el siglo XV sobre los acantilados andinos, mostrando las capas de grava y piedra bajo las terrazas agrícolas que impedían deslizamientos por lluvias torrenciales, la precisión milimétrica de los muros antisísmicos de granito ensamblados sin mortero, y el acueducto de piedra surtiendo agua fresca a las 16 fuentes litúrgicas reales.")

add_int_item("6.1.12.", "Santa Sofía de Constantinopla: cúpula flotando sobre pechinas y mosaicos de oro", 
             "La catedral bizantina del siglo VI que revolucionó la física arquitectónica al sostener una inmensa cúpula sobre cuatro pechinas rodeada de 40 ventanas luminosas.",
             "Corte arquitectónico 3D hiperrealista de la Basílica de Santa Sofía de Constantinopla recién consagrada en el año 537 d.C., mostrando el prodigio estructural de la gran cúpula central de 31 metros flotando sobre cuatro pechinas triangulares de ladrillo, el anillo luminoso de 40 ventanas en la base por donde entran rayos solares, y los interiores deslumbrantes cubiertos de millones de teselas de mosaicos de oro reluciente.")

add_int_item("6.1.13.", "La Ciudad Prohibida de Pekín durante el apogeo imperial de la dinastía Ming", 
             "El complejo palaciego de madera más grande del mundo, con sus techos de tejas amarillas imperiales, encastres de madera sin clavos (dougong) y puentes de jade.",
             "Infografía 3D de corte en perspectiva del Salón de la Suprema Armonía en la Ciudad Prohibida de Pekín en el siglo XV, revelando el asombroso sistema de carpintería tradicional china dougong (soportes de madera encastrados sin un solo clavo de hierro capaces de resistir terremotos), los gigantescos pilares de madera de nanmu dorada y el trono del Dragón Imperial en el centro de un suelo de ladrillos de oro pulido.")

add_int_item("6.1.14.", "La ciudad azteca de Tenochtitlán: calzadas, chinampas y Templo Mayor en el lago", 
             "La metrópolis lacustre flotando sobre las aguas del lago de Texcoco, conectada por grandes calzadas elevadas y abastecida por huertos flotantes de alta productividad.",
             "Reconstrucción 3D panorámica con corte de detalle de Tenochtitlán en 1519 en medio del lago de Texcoco bajo el cielo de la meseta mexicana, mostrando las grandes calzadas de piedra con puentes levadizos, la red de canales recorridos por canoas repletas de flores y maíz, el sistema agrícola ingenioso de las chinampas ganadas al lago con estacas de sauce, y en el corazón ceremonial, las pirámides gemelas de Tláloc y Huitzilopochtli en el Templo Mayor.")

add_int_item("6.1.15.", "La ciudadela de Petra (El Tesoro) tallada en el desfiladero de piedra arenisca roja", 
             "La arquitectura nabatea esculpida directamente de arriba hacia abajo en la roca viva del Siq, oculta con canales secretos de recolección de agua de lluvia en el desierto.",
             "Corte 3D geológico y arquitectónico del Tesoro (Al-Khazneh) en Petra, Jordania, revelando cómo la fachada de columnas corintias de 40 metros fue tallada de arriba hacia abajo directamente en el acantilado vertical de arenisca rosa y naranja, mostrando el interior de la gran cámara funeraria vacía en el corazón de la montaña y los conductos cerámicos ocultos en las paredes exteriores que recogían cada gota de lluvia del desierto.")

add_header_2("6.2. Grandes Máquinas, Vehículos e Infraestructuras por Dentro")
add_int_item("6.2.1.", "Corte transversal del Canal de Panamá: esclusas gigantes y física del agua", 
             "El funcionamiento por gravedad del ascensor acuático para barcos transoceánicos que une el Atlántico y el Pacífico salvando 26 metros de desnivel.",
             "Infografía de corte 3D explicativa del Canal de Panamá durante el paso de un gigantesco buque portacontenedores por las esclusas de Miraflores, mostrando las inmensas compuertas de acero de 20 metros de altura, las galerías subterráneas por donde circulan millones de litros de agua por simple gravedad desde el Lago Gatún sin usar bombas eléctricas, y las locomotoras de remolque fijando el barco desde los muelles laterales.")

add_int_item("6.2.2.", "Submarino abisal descendiendo a 5.000 metros en la Fosa de las Marianas", 
             "La esfera de titanio de 9 cm de grosor capaz de soportar presiones extremas de 1.100 atmósferas, cámaras de flotabilidad e iluminación artificial en la penumbra.",
             "Corte 3D técnico de un batiscafo de exploración oceánica profunda flotando sobre fumarolas hidrotermales a 5.000 metros de profundidad, mostrando la cápsula esférica de titanio de paredes ultra-gruesas donde trabajan tres biólogos marinos rodeados de pantallas, el casco exterior rebosante de espuma de flotabilidad sintética, y los potentes focos LED exteriores iluminando criaturas abisales bioluminiscentes.")

add_int_item("6.2.3.", "Avión comercial Boeing 787 por dentro: cabina de pilotos y dos cubiertas", 
             "La anatomía completa de una aeronave moderna de fibra de carbono desde el radar de morro, cabina de pasajeros, bodega de carga y reactores de turbina.",
             "Infografía longitudinal en corte 3D de un avión de pasajeros Boeing 787 Dreamliner en crucero sobre las nubes, mostrando con total nitidez la cabina de pilotos con sus pantallas HUD frontales, la zona de primera clase y cabina de pasajeros presurizada, las cocinas (galleys), la zona inferior de bodega repleta de contenedores de equipaje en pistas de rodillos, y un corte de detalle de un motor turbofan girando en el ala.")

add_int_item("6.2.4.", "Presa hidroeléctrica por dentro: tuberías forzadas y turbinas Francis de 500 MW", 
             "Cómo se convierte la energía potencial del agua embalsada en electricidad pura mediante conductos subterráneos gigantescos que giran turbinas de acero.",
             "Corte transversal 3D de ingeniería de una gigantesca presa de bóveda de hormigón incrustada en un cañón de montaña, mostrando el muro de retención del embalse de agua azul profundo, la entrada de agua con sus rejillas protectoras, la inmensa tubería forzada subterránea en pendiente inclinada por donde cae el agua a alta presión, y la sala de máquinas en la base donde el chorro hace girar a 300 RPM una turbina Francis acoplada a su alternador eléctrico gigante.")

add_int_item("6.2.5.", "Estación Espacial Internacional (ISS) habitada orbitando a 28.000 km/h", 
             "El laboratorio orbital modular flotando a 400 km sobre la Tierra con sus paneles solares desplegados, módulo de cúpula de observación y reciclaje de agua.",
             "Infografía 3D en corte longitudinal y transparente de varios módulos conectados de la Estación Espacial Internacional (ISS) flotando en el vacío del espacio con la curvatura de la Tierra iluminada de fondo, mostrando a los astronautas en ingravidez haciendo experimentos en el laboratorio Destiny, el módulo de dormitorios con sacos de dormir verticales, la Cúpula de cristal con vistas al planeta y los inmensos paneles solares dorados extendidos hacia el Sol.")

add_int_item("6.2.6.", "El interior de un galeón español del siglo XVII: cañones y bodega de especias", 
             "La fortaleza flotante de la Flota de Indias de tres puentes, con sus velas desplegadas, cureñas de artillería de bronce y cargamento de plata de Potosí.",
             "Corte transversal 3D detallado de un gran galeón español de tres cubiertas navegando en el mar del Caribe en 1630, mostrando la cubierta superior con los mástiles de jarcia y velas de lona hinchadas por el viento, la cubierta de artillería intermedia con filas de cañones de bronce apuntando por las portas abiertas con sus artilleros, y el fondo de la bodega repleto de cofres de plata, barriles de agua dulce, fardos de seda y piedras de lastre para equilibrar la nave.")

add_int_item("6.2.7.", "El interior del Gran Colisionador de Hadrones (LHC) a 100 m bajo tierra", 
             "El anillo de imanes superconductores enfriado al helio líquido (-271 °C) que acelera protones a la velocidad de la luz para recrear el Big Bang.",
             "Infografía 3D de corte subterráneo en la frontera entre Suiza y Francia, revelando el túnel de hormigón de 27 km del Gran Colisionador de Hadrones (LHC) a 100 metros bajo los prados nevados, mostrando la tubería azul de los electroimanes superconductores enfriados por helio líquido, y un corte magnificado de la caverna del detector ATLAS de 25 metros de altura repleta de miles de cables de fibra óptica y sensores registrando la colisión frontal de dos haces de protones con estallidos de luz subatómica.")

add_int_item("6.2.8.", "Corte transversal de un rascacielos súper-alto con péndulo amortiguador", 
             "La estructura de un gigante de 800 metros (estilo Taipei 101 / Burj Khalifa) con su bola de acero de 660 toneladas en la cúspide para contrarrestar tifones.",
             "Corte 3D estructural e ingeniería de un rascacielos ultra-alto de 800 metros en medio de una metrópolis nocturna bajo tormenta de viento, revelando el núcleo central de hormigón de alta resistencia con su haz de ascensores de alta velocidad, las plantas de oficinas y observatorios, y en las plantas superiores entre el piso 87 y 92, la imponente esfera dorada del péndulo amortiguador de masa de 660 toneladas suspendida por cables de acero oscilando suavemente para equilibrar la estructura del edificio.")

add_int_item("6.2.9.", "La Torre Eiffel en 1889: remaches, cimientos y ascensores hidráulicos originales", 
             "El triunfo del hierro forjado de Gustave Eiffel: 18.000 piezas unidas por 2,5 millones de remaches térmicos asentados sobre caissons de aire comprimido en el Sena.",
             "Infografía 3D técnica e histórica de la Torre Eiffel durante su inauguración en la Exposición Universal de París de 1889, mostrando la celosía de vigas de hierro pudelado, los enormes cimientos de mampostería subterránea bajo los pilares cerca del río Sena con cajones de aire comprimido, y el asombroso mecanismo original de los ascensores inclinados Roux-Combaluzier impulsados por enormes émbolos de agua a presión que subían por la curva del pilar.")

add_int_item("6.2.10.", "El interior de un crucero transatlántico moderno: 18 cubiertas y sala de máquinas", 
             "Una ciudad flotante para 6.000 pasajeros con teatro, piscinas en cubierta, potentes motores diésel-eléctricos en la sentina y estabilizadores de aleta abatibles.",
             "Corte lateral 3D monumental de un gigantesco barco crucero moderno navegando por el mar turquesa, mostrando las 18 cubiertas superpuestas que albergan miles de camarotes con balcón exterior, el gran teatro central de tres alturas, la cubierta superior con toboganes acuáticos y piscinas, y en la parte más profunda bajo la línea de flotación, la inmensa sala de máquinas con motores generadores diésel, desalinizadoras de agua potable y las aletas estabilizadoras hidráulicas desplegadas en el agua para evitar el balanceo.")

add_int_item("6.2.11.", "La Catedral de Chartres por dentro: arbotantes, bóvedas de crucería y rosetones", 
             "La revolución del gótico que permitió sustituir muros macizos por paredes gigantescas de cristal de colores gracias al equilibrio de arbotantes y contrafuertes.",
             "Corte arquitectónico 3D pedagógico de la Catedral gótica de Chartres en una tarde soleada, mostrando cómo el peso colosal de las altas bóvedas de crucería de piedra de la nave central (37 metros de altura) es encauzado hacia el exterior y absorbido por los arcos arbotantes voladores y los pesados contrafuertes exteriores, permitiendo que los muros de la iglesia estén formados casi íntegramente por inmensas vidrieras de cristal cobalto azul y rojo que proyectan mosaicos de luz mística sobre las columnas y el laberinto del suelo.")

add_int_item("6.2.12.", "El interior de un panal de abejas en corte macro: celdas hexagonales doradas y miel operculada", 
             "La perfección matemática de la cera de abejas: prismas hexagonales de 120 grados que optimizan el volumen con el mínimo gasto de material biológico, miel dorada y metamorfosis.",
             "Infografía biológica y arquitectónica en corte transversal macro 3D del interior de un panal de abejas silvestre iluminado por luz solar cálida, mostrando la geometría sagrada de los prismas hexagonales de cera pura conectados con precisión matemática, revelando en varias celdas abiertas el néctar floral condensándose en miel dorada resplandeciente sellada con opérculos de cera blanca, en otras celdas contiguas se observan larvas blancas de abejas en distintas fases de metamorfosis flotando sobre jalea real pura, y abejas obreras vertiendo gotas de néctar con sus probóscides.")

add_int_item("6.2.13.", "El interior de un traje espacial actual: capas térmicas, refrigeración y soporte vital", 
             "La mini-nave espacial individual de 14 capas que protege del vacío del espacio, radiación solar, micro-meteoritos a 30.000 km/h y temperaturas de -150 °C a +120 °C.",
             "Infografía en corte por capas 3D (estilo peel-away) de un traje espacial de actividad extravehicular (EMU) de la NASA flotando ante la Estación Espacial Internacional, revelando desde fuera hacia adentro: la capa exterior blanca anti-meteoritos de Kevlar y Nomex, las 7 capas intermedias de aislamiento térmico aluminizado de Mylar, la prenda interior de malla Spandex azul recorrida por 90 metros de tubos finos con agua fría circulante para regular el calor corporal del astronauta, y el interior de la mochila de soporte vital (PLSS) con los tanques de oxígeno puro y depuradores de litio.")

add_int_item("6.2.14.", "El Templo de Artemisa en Éfeso: 127 columnas colosales y estatuas de oro", 
             "Una de las Siete Maravillas de la Antigüedad reconstruida en todo su esplendor jónico con relieves escultóricos policromados y su celda central sagrada.",
             "Reconstrucción arquitectónica 3D hiperrealista del Templo de Artemisa en Éfeso durante el siglo IV a.C., mostrando la imponente fachada de columnas jónicas de mármol de 18 metros esculpidas en su base con relieves policromados, y un corte que permite ver el santuario interior con la estatua colosal de la diosa iluminada por pebeteros de bronce.")

add_int_item("6.2.15.", "Corte transversal del planeta Tierra desde la corteza oceánica al núcleo de hierro", 
             "La anatomía térmica y geológica de nuestro hogar: la fina corteza continental y marina, el manto viscoso en convección lenta, el núcleo exterior líquido que crea el campo magnético y el núcleo interior sólido a 6.000 °C.",
             "Infografía geológica 3D en corte de gajo (estilo pastel) del planeta Tierra suspendido en el espacio negro, mostrando la finísima corteza azul de océanos y continentes, descendiendo hacia el manto superior e inferior de roca ígnea en estado plástico naranja-rojo con corrientes de convección térmica que mueven las placas tectónicas, el océano subterráneo del núcleo externo de hierro y níquel líquido arremolinado produciendo las líneas invisibles del escudo magnético terrestre, y en el centro absoluto, una esfera incandescente blanca de hierro sólido del tamaño de la Luna a 6.000 °C de temperatura.")

add_header_2("6.3. Microcosmos, Ciencia Avanzada y Secretos Naturales")
add_int_item("6.3.1.", "El interior de un chip de ordenador cuántico operando dentro del criostato dorado", 
             "La preciosa lámpara de araña de cobre y oro multicapa (dilution refrigerator) que enfría el procesador cuántico a 15 milikelvins (-273,13 °C), más frío que el espacio interestelar.",
             "Infografía de corte 3D de un ordenador cuántico de vanguardia en un laboratorio estéril, revelando el imponente criostato de dilución abierto (conocido como 'la lámpara de araña de oro'), con sus cinco etapas de placas circulares de cobre pulido chapado en oro purísimo y tupidos manojos de cables coaxiales de microondas que descienden en cascada térmica hasta el fondo, donde se aloja el minúsculo chip de silicio con cúbits superconductores operando a una fracción de grado por encima del cero absoluto rodeado de blindaje magnético.")

add_int_item("6.3.2.", "El interior de nuestro cerebro: corte de resonancia 3D mostrando sinapsis y redes", 
             "La máquina más compleja del universo conocido: 86.000 millones de neuronas interconectadas por 100 billones de sinapsis eléctricas y bioquímicas en constante remodelación neuroplástica.",
             "Corte transversal y zoom microscópico 3D de un cerebro humano encendido con actividad eléctrica, mostrando en gran escala las circunvoluciones del córtex cerebral, el cuerpo calloso y el sistema límbico iluminados con suaves tonos turquesa y violeta; y en un recuadro circular de zoom 50.000x, una red fascinante de neuronas piramidales con sus largas dendritas y axones comunicándose a través de sinapsis que emiten destellos luminosos dorados por el paso de neurotransmisores químicos.")

add_int_item("6.3.3.", "La colosal red de hongos subterránea del bosque (Wood Wide Web): 110 billones de km de micelio", 
             "El increíble hallazgo biológico: cómo una red subterránea global de micelio fúngico interconecta las raíces de los árboles del bosque como una verdadera internet natural para compartir agua, nutrientes y alertas.",
             "Infografía biológica y ecológica en corte transversal 3D del suelo del bosque en sección profunda bajo robles y abetos centenarios, revelando en la capa superficial de tierra vegetal y raíces una asombrosa y luminosa red tejida por billones de finísimos filamentos blancos y dorados de micelio fúngico (la llamada Wood Wide Web micorrízica de 110 billones de kilómetros), mostrando en un recuadro de zoom interactivo cómo los hilos del hongo envuelven las puntas de las raíces del árbol intercambiando minerales por azúcar de la fotosíntesis y enviando señales químicas fosforescentes de alerta y nutrientes de un árbol madre viejo a un pequeño brote joven en la sombra.")

add_int_item("6.3.4.", "Corte transversal de nuestro propio Sol: núcleo de fusión atómica y corona dorada", 
             "El generador nuclear que sostiene la vida: 600 millones de toneladas de hidrógeno fundidas en helio cada segundo en un núcleo a 15 millones de grados.",
             "Corte 3D astronómico de nuestra estrella, el Sol, mostrado en sección de cuarto de esfera resplandeciente, revelando en el centro el núcleo ultradenso de fusión termonuclear de color blanco-azulado radiante a 15 millones de grados, rodeado por la amplia zona radiativa donde los fotones tardan 100.000 años en atravesar la densidad del plasma, la zona convectiva exterior con enormes burbujas de gas caliente subiendo a la superficie como sopa hirviendo, la fotosfera con manchas solares oscuras y arcos magnéticos prominentes, y la corona exterior de filamentos de luz dorada.")

add_int_item("6.3.5.", "El interior de una cueva de cristales gigantes (Naica, México) a 50 °C de temperatura", 
             "El palacio de cristal subterráneo a 300 metros bajo tierra donde formaciones de selenita pura de 12 metros de largo crecieron lentamente durante medio millón de años en agua mineralizada.",
             "Infografía y vista 3D inmersiva del interior de la Cueva de los Cristales de Naica en Chihuahua, México, mostrando una cavernosa cámara subterránea cruzada en todas direcciones por vigas e inmensos pilares facetados de cristal de selenita translúcida de hasta 12 metros y 55 toneladas de peso resplandeciendo como espadas de luz blanca, con exploradores vestidos con trajes de refrigeración anaranjados de respirador especial escalando con cuerdas entre los cristales gigantes para mostrar la escala colosal del entorno.")

add_int_item("6.3.6.", "Corte 3D de un volcán en erupción: cámara magmática subterránea y chimenea principal", 
             "La plomería térmica de nuestro planeta en acción: cómo la presión del gas disuelto en el magma asciende por fracturas geológicas hasta desencadenar una columna eruptiva de ceniza y lava ardiente.",
             "Corte transversal geológico 3D de un gran estratovolcán en plena erupción durante el crepúsculo, mostrando a 5 kilómetros bajo la montaña la enorme cámara magmática incandescente llena de lava roja viscosa a 1.200 °C y gases a presión, la chimenea central vertical y conductos secundarios por donde asciende el magma fundiendo la roca circundante, el cráter superior escupiendo ríos de lava basáltica incandescente por las laderas, y una altísima columna de cenizas volcánicas y rayos estáticos (tormenta sucia) elevándose hacia la estratosfera.")

add_int_item("6.3.7.", "El interior de un reloj astronómico medieval (estilo Praga) con sus apóstoles y engranajes", 
             "La maravilla mecánica del siglo XV que mide la hora solar, fases lunares, constelaciones del zodiaco y hace desfilar cada hora figuras mecánicas de autómatas movidas por pesas de piedra.",
             "Corte 3D de precisión mecánica e histórica de la torre del Reloj Astronómico de Praga (Orloj) visto desde dentro y fuera simultáneamente, mostrando en el exterior las coloridas esferas astrológicas doradas y las ventanas abiertas por donde desfilan las estatuillas de madera de los 12 apóstoles; y en el interior de la torre de piedra, la asombrosa maquinaria de relojería forjada en hierro del año 1410, con ruedas dentadas gigantescas, péndulos oscilantes, escapes de paletas y grandes cuerdas que sostienen pesas de piedra labrada bajando lentamente por el pozo.")

add_int_item("6.3.8.", "La fortaleza hidráulica y madriguera del castor: dique, cúpula de dos pisos y entrada submarina", 
             "La mayor obra de ingeniería civil del reino animal: cómo embalsan ríos para crear lagunas que no se congelan y construyen su refugio fortificado invulnerable con acceso 100% bajo el agua.",
             "Infografía arquitectónica y biológica en corte longitudinal 3D de una laguna del bosque con el dique y la gran madriguera fortificada construida por una familia de castores en medio del agua, mostrando en sección el dique exterior de troncos entrelazados y barro que mantiene el nivel de agua constante, y en el centro, la cúpula cónica de ramas con un corte interior revelando sus dos alturas: el túnel de entrada secreto sumergido bajo la superficie por donde entra el castor buceando a salvo de depredadores terrestres, el comedor inferior en seco donde se escurren el agua del pelaje, el dormitorio superior cálido alfombrado de virutas secas donde descansan las crías, y el respiradero superior entre ramas sueltas que hace de chimenea.")

add_int_item("6.3.9.", "El interior microscópico del ojo humano: córnea, cristalino y retina en alta definición", 
             "La cámara fotográfica perfecta de la evolución: cómo la luz atraviesa la córnea transparente, es enfocada automáticamente por el cristalino flexible y proyectada en el mosaico óptico de 120 millones de bastones y conos de la retina.",
             "Infografía médica y anatómica 3D en corte sagital del ojo humano recibiendo un haz de luz exterior de un paisaje nevado, revelando la cúpula transparente exterior de la córnea, el iris azul con la pupila contraída por la luminosidad, la lente biconvexa cristalina suspendida por fibras del músculo ciliar que enfocan la imagen, la cavidad interior transparente llena de gel de humor vítreo, y la superficie interna posterior de la retina ampliada en un recuadro mostrando el bosque celular microscópico de conos sensitivos al color y bastones sensitivos a la penumbra conectados al nervio óptico hacia el cerebro.")

add_int_item("6.3.10.", "El interior de una turbina eólica flotante en alta mar de 15 megavatios por dentro", 
             "Los gigantes del mar: torres de acero de 150 metros de altura sobre plataformas flotantes ancladas al fondo marino, coronadas por una nacela del tamaño de un edificio con multiplicadora de engranajes y generador gigante.",
             "Corte transversal 3D técnico de una colosal turbina aerogeneradora marina de 15 MW instalada en aguas profundas del Atlántico, mostrando las tres palas gigantes de 115 metros de fibra de vidrio girando en el viento marino, un corte de detalle de la nacela superior (del tamaño de un palacio de dos plantas) con la caja multiplicadora de engranajes planetarios y el enorme anillo del generador eléctrico principal refrigerado por agua, el tubo vertical de la torre con el ascensor interior para técnicos, y la plataforma flotante semisumergible en el mar unida con cadenas de acero colosales al lecho marino a 200 metros de profundidad.")

add_int_item("6.3.11.", "Corte transversal del telescopio espacial James Webb (JWST) y sus espejos de oro", 
             "El ojo de la humanidad en el infrarrojo flotando en el Punto de Lagrange L2 a 1,5 millones de km, con su escudo térmico plegable de 5 capas de Kapton que enfría los instrumentos a -233 °C en la sombra eterna.",
             "Infografía de corte 3D e ingeniería espacial del Telescopio Espacial James Webb (JWST) flotando en el espacio interestelar profundo, mostrando la gran flor del espejo primario desplegado de 6,5 metros compuesto por 18 segmentos hexagonales de berilio recubiertos con una levísima capa de oro puro reflectante, el espejo secundario en sus báculos de fibra de carbono, y un corte del módulo de instrumentos ISIM en la sombra protegiéndose del calor del Sol y de la Tierra gracias al inmenso escudo parasol rosado de 5 capas separadas de membrana Kapton milimétricamente tensada.")

add_int_item("6.3.12.", "Corte 3D de un túnel subterráneo de levitación magnética cruzando bajo el mar", 
             "La movilidad ultrarrápida del siglo XXI: trenes maglev en túneles al vacío (Hyperloop o Maglev submarino) viajando a 600 km/h sin rozamiento ni ruido protegidos por anillos de hormigón reforzado.",
             "Corte arquitectónico y de ingeniería 3D de un túnel ferroviario submarino de levitación magnética (Maglev) cruzando a 50 metros bajo el lecho rocoso de un océano profundo, mostrando el revestimiento exterior con dovelas de hormigón armado de alta densidad selladas herméticamente contra la presión del agua, el conducto central en semivacío, y un tren de morro aerodinámico blanco y plata deslizándose suavemente a 600 km/h suspendido 1 centímetro en el aire sobre los raíles guía electromagnéticos brillantes sin ningún contacto físico ni vibración.")

add_int_item("6.3.13.", "El rascacielos bioclimático de las termitas brújula: chimeneas solares y aire acondicionado pasivo", 
             "La torre ecológica perfecta del reino animal: cómo montículos de tierra de 8 metros orientados de norte a sur mantienen su interior a 30 °C exactos en el calor extremo de la sabana gracias a la convección térmica.",
             "Infografía arquitectónica en corte longitudinal 3D de un imponente montículo o termitero brújula de 8 metros de altura en plena sabana africana bajo un sol abrasador, mostrando en sección transversal su asombrosa ingeniería bioclimática pasiva que inspiró la arquitectura ecológica moderna: una gran chimenea central vertical por donde asciende y escapa el aire caliente, canales perimetrales en los muros por donde circula el aire enfriándose por la porosidad de la arcilla, y en el sótano subterráneo protegido, la cámara real con la reina y miles de obreras junto a las grandes granjas agrícolas subterráneas de cultivo de hongos que se mantienen a una temperatura constante e ideal de 30 °C.")

add_int_item("6.3.14.", "Corte transversal de una gran batería de coche eléctrico de litio o estado sólido", 
             "El corazón de la movilidad limpia: cientos de celdas prismáticas o cilíndricas organizadas en módulos dentro de una carcasa blindada en el suelo del vehículo, con placas de refrigeración por glicol y gestión inteligente BMS.",
             "Corte 3D técnico y de alta resolución del paquete de baterías integrado en la plataforma plana de un vehículo eléctrico de lujo, revelando la estructura de seguridad exterior con bastidor de aluminio de alta resistencia a impactos, el interior ordenado en 24 módulos independientes que contienen miles de celdas de iones de litio o estado sólido conectadas por barras colectoras de cobre puro, el circuito inferior de canales serpenteantes por donde circula líquido refrigerante azul para mantener la temperatura óptima a 25 °C, y la placa electrónica central del Sistema de Gestión de Batería (BMS) vigilando el voltaje de cada celda.")

add_int_item("6.3.15.", "El Coliseo de Roma por dentro: velas desplegadas y fosos subterráneos", 
             "El ingenioso sistema hidráulico del hipogeo, jaulas de fieras y el toldo (velarium) desplegado por marineros para proteger del sol a 50.000 espectadores.",
             "Corte transversal 3D detallado del Coliseo de Roma en el año 80 d.C., mostrando en la mitad superior el graderío lleno bajo el toldo de tela del velarium, y en el corte inferior el laberinto subterráneo de fosos, poleas de madera y montacargas hidráulicos que elevaban a los leones y gladiadores a la arena.")

add_header_2("6.4. Síntesis y Maravillas Culturales e Históricas del Mundo")
add_int_item("6.4.1.", "El Templo Mayor de Angkor Wat en Camboya por dentro: fosos y santuario en la selva", 
             "El monumento religioso más grande del planeta construido en el siglo XII en piedra arenisca sin mortero, rodeado por un foso de agua de 190 metros que equilibra el peso del edificio sobre el suelo pantanoso de la jungla.",
             "Corte arquitectónico y vista aérea 3D de Angkor Wat en Camboya durante el amanecer equinoccial, mostrando la pirámide sagrada de tres niveles culminada en cinco grandes torres en forma de capullo de loto, un corte transversal que revela las empinadas escaleras de piedra que suben al santuario central de Vishnu, los interminables pasillos de galerías con bajorrelieves escultóricos de batallas celestiales, y el enorme foso de agua perimetral rodeado de árboles tropicales centenarios de raíces gigantescas.")

add_int_item("6.4.2.", "Reconstrucción del palacio omeya de Medina Azahara (Córdoba) en su máximo esplendor", 
             "La 'Ciudad Brillante' construida por Abderramán III a los pies de Sierra Morena en el año 936, dispuesta en tres terrazas escalonadas con el Salón Rico de mármoles tallados y albercas de azogue reflectante.",
             "Reconstrucción arquitéctónica en corte isométrico 3D de la ciudad palatina de Medina Azahara en Córdoba en el siglo X, mostrando su dramática disposición en tres terrazas escalonadas en la ladera de la montaña: la superior con el Alcázar y estancias reales, la intermedia con jardines paradisiacos, y la inferior con la gran mezquita y ciudad de corte; y en un corte de detalle ampliado, el esplendoroso Salón Rico del califa con arcos de herradura bicolores en rojo y blanco, paredes labradas en ataurique de mármol de Estepa y una gran fuente central cubriendo una alberca que emitía destellos al sol.")

add_int_item("6.4.3.", "Reconstrucción de la antigua Jerusalén del siglo I con el Segundo Templo del Monte Sión", 
             "El monumental complejo sagrado ampliado por Herodes el Grande en el Monte del Templo con inmensas explanadas soportadas por muros ciclópeos de piedra blanca y el santuario cubierto de placas de oro deslumbrante.",
             "Corte 3D panorámico y reconstrucción histórica de la ciudad de Jerusalén en el año 30 d.C., dominada en el centro por la gran explanada del Monte del Templo y el Segundo Templo reconstruido en piedra blanca de Judea, mostrando el atrio exterior de los gentiles con el pórtico Real de columnas corintias, las puertas de bronce corintio pulido, y un corte en el santuario interior revelando el Lugar Santo con el candelabro de oro de siete brazos (Menorá), el altar del incienso y el velo púrpura que ocultaba el Sancta Sanctorum.")

add_int_item("6.4.4.", "Reconstrucción virtual del Circo Máximo de Roma en plena carrera de cuadrigas", 
             "El estadio deportivo de mayor capacidad jamás construido en la historia del hombre: una pista de arena de 600 metros de largo en un valle romano capaz de albergar a 150.000 o hasta 250.000 espectadores gritando al unísono.",
             "Infografía 3D de gran angular del Circo Máximo de Roma en el siglo II d.C. durante los juegos imperiales en una tarde soleada, mostrando los inmensos graderíos de tres niveles en mármol y piedra repletos de más de 150.000 ciudadanos vestidos de togados y colores de las cuatro facciones (rojo, blanco, azul y verde), la espiral central de la pista de arena (spina) adornada con un obelisco egipcio importado por Augusto y fuentes de agua con delfines de bronce que contaban las vueltas, y cuatro veloces cuadrigas de caballos al galope doblando la curva en una nube de polvo dorado.")

add_int_item("6.4.5.", "Torre solar termoeléctrica por dentro con sus espejos heliostatos y receptor de sales", 
             "La alquimia solar moderna: miles de espejos de seguimiento solar sincronizados apuntan a lo alto de una torre de 250 metros para calentar sal fundida a 565 °C y generar electricidad de día y también por la noche.",
             "Corte 3D de ingeniería de una gigantesca planta de energía solar térmica de torre central en medio del desierto claro bajo un sol cegador, mostrando un campo circular con 10.000 espejos heliostatos inteligentes girando para concentrar sus rayos solares en un punto luminoso en lo alto de una torre de hormigón de 250 metros; y un corte transversal de la cúspide revelando el receptor cerámico donde la sal fundida absorbe el calor extremo, descendiendo por tuberías interiores aisladas hasta los tanques de almacenamiento térmico en la base capaces de hacer hervir agua y mover turbinas de vapor durante la noche o días nublados.")

add_int_item("6.4.6.", "Reconstrucción de la legendaria Troya en la Edad del Bronce con sus murallas concéntricas", 
             "La imponente fortaleza del rey Príamo descrita por Homero en la Ilíada (Troya VI/VIIa), con sus empinados muros inclinados de piedra caliza, la puerta Escea con torreones de guardia y el palacio real en la acrópolis.",
             "Infografía arqueológica e histórica 3D de la ciudad de Troya (capa arqueológica Troya VI) durante la Edad del Bronce en las costas del mar Egeo del siglo XIII a.C., mostrando en corte las imponentes murallas defensivas inclinadas construidas con grandes bloques de piedra caliza tallados con suma precisión, las torres defensivas protegiendo la puerta principal, las casas de dos plantas con cimientos de piedra y techos planos de arcilla, y en el punto más elevado de la colina de Hisarlik, el palacio real del megarón micénico con un patio interior arbolado.")

add_int_item("6.4.7.", "Reconstrucción de la Alhambra de Granada en el siglo XIV con sus fuentes y estucos", 
             "La cumbre de la arquitectura palatina nazarí: cómo se combinaron proporciones geométricas sagradas, estucos tallados con poesía epigráfica en caligrafía árabe y una avanzada red de acequias para crear un paraíso terrenal.",
             "Reconstrucción y corte arquitectónico 3D hiperrealista del Palacio de los Leones en la Alhambra de Granada en el siglo XIV bajo una suave luz de tarde otoñal, mostrando el patio central con la famosa fuente de los doce leones de mármol de Macael arrojando hilos de agua cristalina por sus bocas, el corte de las salas perimetrales (Dos Hermanas y Abencerrajes) revelando las asombrosas cúpulas de mocárabes de yeso que cuelgan del techo como estalactitas geométricas policromadas, y los canalillos de agua surcando el suelo de mármol conectando el interior con los jardines de arrayanes exteriores.")

add_int_item("6.4.8.", "Corte transversal del Puente Golden Gate en San Francisco: cables y torres de acero", 
             "El prodigio colgante del Art Déco de 1937 de 2.737 metros de largo cruzando la bahía: cómo dos cables principales compuestos por 27.572 alambres de acero individuales trenzados soportan el tablero colgante sobre las aguas turbulentas del Pacífico.",
             "Corte técnico e infografía 3D de alta definición del Puente Golden Gate de San Francisco envuelto parcialmente por una niebla marina al amanecer (color naranja internacional), mostrando en corte la estructura de una de las torres principales de acero celular ascendiendo 227 metros sobre el agua, los masivos bloques de anclaje de hormigón en las dos orillas fijados a la roca viva, y un corte magnificado de uno de los dos cables principales de 92 centímetros de diámetro revelando en su interior la compactación exacta de 27.572 alambres individuales de acero galvanizado tensados uno a uno que sostienen las péndolas verticales del tablero de tráfico de 6 carriles.")

add_int_item("6.4.9.", "Reconstrucción del Palacio de Cnossos en Creta: frescos del salto del toro y laberinto", 
             "La cuna de la civilización minoica en el 1500 a.C.: un palacio de varios pisos con pozos de luz, columnas rojas invertidas más anchas arriba que abajo, el primer sistema de fontanería con agua corriente de la historia y frescos marinos deslumbrantes.",
             "Corte arquitectónico 3D en perspectiva multinivel del Palacio Real de Cnossos en la isla de Creta durante la Edad del Bronce (c. 1500 a.C.), revelando su intrincada disposición que inspiró el mito del Laberinto del Minotauro: patios centrales iluminados por ingeniosos pozos de luz verticales que daban ventilación y claridad a cuatro plantas superpuestas, las características columnas minoicas de madera pintadas en rojo vibrante y negro con capiteles redondos, el Salón del Trono con la silla real de alabastro y frescos en la pared de grifos florales, y en los pisos inferiores, las tuberías de terracota encastradas que llevaban agua potable fresca desde los manantiales de montaña y evacuaban el drenaje en la primera red de alcantarillado del mundo antiguo.")

add_int_item("6.4.10.", "Corte transversal de un submarino nuclear de la Armada: sala de reactor y camarotes", 
             "La verdadera nave de los océanos: un submarino de combate clase Virginia o Astute capaz de permanecer sumergido durante meses enteros produciendo su propia agua dulce y oxígeno a partir de la sal marina gracias a su reactor nuclear de uranio enriquecido.",
             "Infografía en corte longitudinal 3D hiperrealista de un gran submarino nuclear de ataque navegando en silencio por las profundidades oscuras del océano norteamericano a 200 metros de profundidad, mostrando de proa a popa: la gran cúpula esférica del sonar pasivo en la nariz, la sala de torpedos y tubos de lanzamiento, el centro de mando y control (CIC) bajo la vela periscópica con oficiales observando monitores tácticos iluminados en azul, la zona intermedia con las literas y cocina del comedor para 130 tripulantes, la sala sellada con blindaje de plomo del reactor nuclear de agua a presión en el centro del buque, y en la popa, las silenciosas turbinas de vapor haciendo girar la hélice de impulsión encapsulada que no genera burbujas ni cavitación.")

add_int_item("6.4.11.", "Corte transversal de un hábitat polar antártico sobre esquíes adaptado al frío extremo", 
             "La arquitectura científica en el lugar más hostil de la Tierra (estilo Estación Halley VI): módulos rojos y azules montados sobre patas hidráulicas elevables con enormes esquíes de acero que impiden quedar enterrados bajo la nieve antártica en inviernos de -70 °C.",
             "Corte arquitectónico y técnico 3D de una base de investigación científica antártica ultramoderna (módulos encadenados estilo Halley VI) asentada sobre una inmensa plataforma de hielo flotante blanca bajo el cielo estrellado de la noche polar con auroras verdes en el firmamento, mostrando los módulos aerodinámicos de fibra de vidrio de color rojo y azul brillante elevados 4 metros sobre la nieve gracias a patas hidráulicas telescópicas terminadas en gigantescos esquíes que se elevan mecánicamente cada año para no ser sepultados por las ventiscas de nieve; revelando en el corte interior el módulo central de comedor y ocio con grandes ventanas de triple cristal térmico, los laboratorios meteorológicos, la planta de generación diésel limpia y reciclaje de agua grises, y los dormitorios de los científicos aislados térmicamente con aerogel para mantener una temperatura interior acogedora de +22 °C mientras fuera soplan vientos huracanados a -65 °C.")

add_int_item("6.4.12.", "Reconstrucción del Templo Mayor del Imperio Inca en el Cuzco (El Coricancha)", 
             "El 'Recinto de Oro' sagrado del Cuzco antes de 1533: muros sillería de diorita oscura tallada y pulida como un espejo sin ninguna junta visible, forrados interior y exteriormente con planchas de oro macizo que reflejaban el sol naciente en el jardín de estatuas de oro.",
             "Reconstrucción y corte 3D histórico e impresionante del sagrado templo inca del Coricancha en el centro imperial del Cuzco a principios del siglo XVI bajo la luz dorada del amanecer andino, revelando la prodigiosa cantería incaica de muros curvados de piedra oscura pulida ensamblados a la perfección milimétrica sin mortero, mostrando el muro exterior de piedra recubierto en su friso superior por una banda continua de oro macizo de dos palmos de ancho, y en el interior del patio sagrado, el asombroso Jardín del Sol rebosante de representaciones artísticas labradas en oro puro a tamaño natural: espigas de maíz con hojas de plata, llamas doradas con sus pastores y flores cósmicas que brillaban deslumbrando a los sacerdotes del Sol.")

add_int_item("6.4.13.", "El edificio de apartamentos colgante del pájaro tejedor republicano: 100 compartimentos y climatización", 
             "La mayor estructura comunitaria de las aves: una cúpula colgante de ramas y paja que envuelve el tronco de un árbol del desierto, albergando hasta 500 pájaros en cámaras individuales térmicas.",
             "Infografía arquitectónica y ornitológica en corte transversal 3D de un enorme nido comunitario del pájaro tejedor republicano envolviendo la gran rama horizontal de una acacia en el desierto del Kalahari, mostrando un corte frontal que revela un verdadero bloque residencial biológico de 100 cámaras o compartimentos independientes separados por muros de paja tejida: las entradas tubulares orientadas verticalmente hacia abajo para impedir el acceso de serpientes trepadoras, las cámaras exteriores ventiladas y frescas utilizadas por las aves para dormir en las calurosas tardes de verano, y las cámaras centrales más profundas y abrigadas donde la colonia agrupa su calor corporal durante las gélidas noches de invierno bajo cero.")

add_int_item("6.4.14.", "Corte de una casa ecológica pasiva de balance cero de energía (Passivhaus) moderna", 
             "El hogar de máxima eficiencia térmica y confort: aislamiento perimetral supergrueso, ventanas triples bajo gas argón, paneles solares en cubierta vegetal, bomba de calor geotérmica y ventilación mecánica con recuperación de calor del 95% sin fugas ni corrientes.",
             "Corte transversal e infografía 3D pedagógica de una vivienda unifamiliar moderna de madera cross-laminated (CLT) construida según el estándar ultra-eficiente Passivhaus en un bosque otoñal, revelando en sección técnica las 5 claves del aislamiento termodinámico: muros exteriores con 30 centímetros de aislamiento continuo de fibra de madera sin ningún puente térmico, ventanas de triple acristalamiento hermético con gas argón y marcos de alta eficiencia en el sur para captar el sol de invierno, la cubierta ajardinada con paneles fotovoltaicos y de agua caliente solar, y en el sótano técnico, el corazón de la casa mostrando el sistema de ventilación mecánica controlada (VMC) con un intercambiador de calor de doble flujo que recupera el 95% del calor del aire viciado que sale para calentar gratis el aire fresco y filtrado que entra desde el exterior sin necesidad de radiadores clásicos.")

add_int_item("6.4.15.", "Síntesis [INT]: Corte 3D comparativo Panteón de Roma vs Cúpula Lunar Tierra-Cosmos", 
             "El arco de la arquitectura humana desde el año 125 d.C. hasta el año 2040: cómo los principios matemáticos del arco y la cúpula autoportante inventados por los arquitectos romanos en hormigón volcánico son la base geométrica de los hábitats presurizados construidos con regolito sinterizado por impresoras 3D en la superficie del Polo Sur de la Luna.",
             "Infografía comparativa e inspiradora en corte 3D dividida en dos mitades simétricas por un eje luminoso central que conecta el pasado y el futuro de la ingeniería humana: a la mitad izquierda, el clásico corte del Panteón de Roma en el año 125 d.C. bajo el sol de Italia con su majestuosa cúpula de casetones de hormigón de piedra pómez de 43 metros de diámetro y su óculo solar abierto al cielo azul iluminando el suelo de mármol; y en perfecta simetría a la mitad derecha, una cúpula hábitat lunar de la NASA en el Polo Sur de la Luna en el año 2040 bajo un cielo negro con la Tierra resplandeciente en el horizonte, mostrando en corte la cúpula protectora exterior de 43 metros construida mediante capas de regolito lunar sinterizado por robots de impresión 3D para frenar la radiación cósmica y los meteoritos, revelando en su interior presurizado y climatizado un jardín aeropónico de cultivo de hortalizas verdes multinivel alimentado por luces LED de espectro rosa que produce oxígeno y alimentos para los exploradores lunares.")

# ==============================================================================
# BLOQUE 7: LÍNEA DE TIEMPO DEL FUTURO Y SCI-FI (@N.AG.A) [FUT]
# ==============================================================================
add_header_1("VII. LÍNEA DE TIEMPO DEL FUTURO Y SCI-FI (@N.AG.A — 60 SESIONES CRONOLÓGICAS)")

add_header_2("7.1. El Futuro Cercano: Revolución IA, Medicina y Hábitats (2028 - 2065)")
add_fut_item("7.1.1.", "Año 2028: El asistente robótico compasivo en el hogar familiar mayores", 
             "La llegada de los primeros robots humanoides de asistencia en el hogar (estilo Tesla Bot / Figure AI), diseñados para ayudar en tareas domésticas pesadas con total suavidad, empatía y seguridad con las personas mayores.",
             "Infografía 3D hiperrealista y emotiva ambientada en el salón cálido y luminoso de una casa de campo mediterránea en el año 2028, mostrando a un amable y estético robot asistente humanoide de color blanco mate y detalles en madera natural que sostiene con delicadeza una bandeja con té caliente sonriendo con sus ojos de luz LED suave, conversando tranquilamente con una pareja de ancianos felices que están sentados en un sillón leyendo un libro frente a un ventanal que da a un jardín soleado.")

add_fut_item("7.1.2.", "Año 2030: Gafas de realidad mixta y traducción simultánea universal en viajes", 
             "El fin de las barreras lingüísticas: gafas ligeras y elegantes que proyectan subtítulos holográficos en tiempo real y traducen la voz de cualquier persona o cartel en un país extranjero.",
             "Infografía 3D de primera persona (POV) y corte explicativo en las bulliciosas calles de Tokio en 2030 por la noche bajo luces de neón, mostrando a un viajero sénior con unas elegantes gafas de montura ligera de realidad mixta; a través de los cristales, los letreros japoneses de las tiendas se transforman automáticamente en castellano claro con letras holográficas doradas flotando en el aire, mientras una guía turística local habla en japonés y junto a ella aparece en tiempo real una burbuja visual de subtítulos traducidos con total naturalidad.")

add_fut_item("7.1.3.", "Año 2033: Agricultura vertical urbana e invernaderos hidropónicos en rascacielos", 
             "Cómo las ciudades producen el 100% de sus verduras frescas dentro de torres de cristal de 30 plantas con luces LED y cultivos sin tierra donde se ahorra el 95% de agua dulce.",
             "Infografía arquitectónica en corte 3D de un rascacielos invernadero vertical en el centro de una gran capital europea en el año 2033, mostrando por dentro 20 plantas transparentes repletas de bandejas escalonadas de lechugas, fresas y tomates creciendo en bandejas de agua enriquecida con nutrientes (hidroponía) bajo una luz ambiental de color rosa y violeta de focos LED de alta eficiencia, donde pequeños drones de recolección automatizados cosechan frutos maduros mientras los residentes del edificio compran hortalizas recién cosechadas en el mercado ecológico de la planta baja.")

add_fut_item("7.1.4.", "Año 2035: Terapia génica personalizada y vacunas universales contra el cáncer y alzhéimer", 
             "La era de la medicina molecular de precisión donde nanosensores detectan cualquier anomalía en el torrente sanguíneo antes de que aparezcan síntomas, curando enfermedades antes de nacer.",
             "Infografía biomédica 3D científica y esperanzadora en el año 2035 de nivel molecular y hospitalario, mostrando en un lado un centro de diagnóstico regenerativo lleno de luz donde una doctora muestra en un holograma flotante el ADN completamente reparado de un paciente sénior sonriente; en la mitad derecha, una ilustración celular hiperdetallada ilustra cómo 'nanobots linfocitarios y vacunas de ARN de cuarta generación' de color oro y cian identifican y eliminan de forma altamente selectiva y limpia una célula degenerada o placa amiloide en el cerebro sin dañar el tejido sano en absoluto.")

add_fut_item("7.1.5.", "Año 2038: Redes eléctricas inteligentes cuánticas y reactores modulares de fusión SMR", 
             "La independencia energética limpia: pequeñas centrales modulares que caben en un edificio escolar y suministran energía ilimitada sin residuos a barrios enteros mediante IA de red cuántica.",
             "Corte transversal 3D e infografía de ingeniería limpia de una mini-central de energía del año 2038 en las afueras verdes de una ciudad sostenible, mostrando en sección un Reactor Modular Pequeño de Fusión (SMR) de contención magnética brillante en color azul zafiro e inmerso en una piscina de agua ultrapura traslúcida; desde el centro de control superior con pantallas holográficas cuánticas, un equipo de ingenieros monitoriza la distribución sin pérdidas de energía limpia y gratuita que alimenta silenciosamente a miles de viviendas con paneles solares transparentes e invernaderos de barrio.")

add_fut_item("7.1.6.", "Año 2040: Drones urbanos de transporte de pasajeros (eVTOL) y aeropuertos en azoteas", 
             "El fin de los atascos: aerotaxis eléctricos silenciosos e independientes que conectan hospitales, aeropuertos y azoteas de rascacielos en 5 minutos sin emisiones ni ruido de hélices clásicas.",
             "Infografía de transporte futurista y urbana 3D en el año 2040 sobre el cielo crepuscular de Madrid o Barcelona, mostrando la azotea ajardinada de un rascacielos convertida en un 'Vertipuerto' (aeropuerto de despegue vertical) de diseño orgánico con plataformas de carga magnética circulares luminosas de donde despegan y aterrizan con total suavidad varios elegantes aerotaxis eléctricos (eVTOL) con alas basculantes y cabinas panorámicas transparentes transportando ejecutivos y turistas en paz y sin contaminación acústica.")

add_fut_item("7.1.7.", "Año 2042: Regeneración de órganos 3D con biotinta de células madre propias del paciente", 
             "El fin de las listas de espera para trasplantes: bio-impresoras hospitalarias que fabrican un corazón, riñón o cartílago nuevo en 48 horas utilizando las propias células del enfermo sin rechazo.",
             "Infografía médica y tecnológica 3D de alta precisión en un quirófano de medicina regenerativa del año 2042, mostrando una avanzada 'Bio-Impresora Quiral 3D' dentro de una cámara estéril de cristal iluminada en luz cian suave, imprimiendo capa a capa con precisión celular milimétrica un corazón humano completamente funcional utilizando un hidrogel rosado de 'biotinta' cultivada a partir de las propias células madre del paciente; al lado se aprecia una pantalla médica con el modelo computacional 3D vascular del órgano palpitando con vida propia.")

add_fut_item("7.1.8.", "Año 2045: Carne cultivada celular en laboratorios de alta cocina sin maltrato animal", 
             "La revolución gastronómica y ética: filetes de wagyu, salmón y pollo producidos a partir de células musculares en fermentadores biológicos con un sabor, textura y nutrición 100% idénticos.",
             "Infografía gastronómica y tecnológica 3D dividida en dos zonas: a la izquierda, la vista limpia y estética de un 'Biorreactor Gourmet' comunal de acero inoxidable y vidrio en una granja urbana vertical donde se cultivan de forma eficiente fibras musculares y proteínas puras; y a la derecha, la presentación en la mesa de un restaurante de estrella Michelin del año 2045 donde se sirve un espectacular y exquisito filete de carne cultivada con un marmoleado perfecto y verduras asadas, demostrando que la alta cocina es ya 100% libre de sacrificio animal y con huella de carbono cero.")

add_fut_item("7.1.9.", "Año 2050: La Base Lunar 'Artemis-Shackleton' permanente en el Polo Sur de la Luna", 
             "La primera colonia humana autosuficiente fuera de la Tierra: cúpulas presurizadas construidas con regolito impreso en 3D en los cráteres lunares donde siempre brilla el sol y hay hielo.",
             "Infografía espacial 3D de altísimo realismo en el año 2050 de la 'Colonia Lunar Shackleton' instalada en el borde del cráter del Polo Sur de la Luna, mostrando varias cúpulas geodésicas de hábitat protegidas por gruesas capas de regolito lunar gris impreso por robots rover 3D; paneles solares verticales altísimos captan la luz rasante y perpetua del sol polar, mientras en primer plano invernaderos cilíndricos transparentes muestran huertos de bambú y hortalizas bajo luz LED rosa con la Tierra azul y blanca suspendida hermosamente en el cielo negro estrellado.")

add_fut_item("7.1.10.", "Año 2055: Úteros artificiales bio-sintéticos (Ectogénesis) para premadurez extrema", 
             "La incubadora del futuro: cámaras de líquido amniótico sintético que permiten salvar la vida de bebés nacidos a las 18 semanas de gestación y eliminan el riesgo de mortalidad en partos complejos.",
             "Infografía médica e ingeniería biológica 3D tierna y esperanzadora de una sala de 'Neonatología Ectogenética' del año 2055 en un hospital infantil universitario, mostrando varias cápsulas de incubación transparentes de diseño ovular llenas de líquido amniótico sintético cálido donde flotan plácidamente y en perfecta seguridad bebés prematuros conectados por cordones umbilicales artificiales de fibra óptica que les suministran oxígeno y nutrientes a temperatura exacta; en una pantalla exterior, unos padres emocionados observan en tiempo real y con total claridad cómo crece y sonríe su bebé dentro de su matriz protectora transparente.")

add_fut_item("7.1.11.", "Año 2058: Ciber-prótesis biónicas neuro-conectadas con tacto de seda", 
             "La superación absoluta de la discapacidad: brazos y piernas mecatrónicas ultraligeras de fibra de carbono y grafeno que se conectan al sistema nervioso periférico y transmiten sensaciones térmicas al cerebro.",
             "Infografía biomédica 3D inspiradora del año 2058 mostrando en primer plano y con corte técnico explicativo una mano biónica de grafeno negro y oro rosa acoplada al antebrazo de una pianista o cirujano sénior, revelando en sección los micro-sensores táctiles de la yema de los dedos artificiales y los interfaces neurales que se integran con los nervios biológicos; la imagen captura el momento conmovedor en el que la mano biónica acaricia con extrema suavidad el pétalo delicado de una rosa, transmitiendo al cerebro del usuario la sensación exacta de suavidad, temperatura y textura por primera vez tras un accidente.")

add_fut_item("7.1.12.", "Año 2060: Hoteles orbitales de gravedad artificial con cúpula panorámica a la Tierra", 
             "El turismo espacial accesible: ruedas giratorias espaciales de 500 metros de diámetro donde la fuerza centrífuga genera gravedad similar a la terrestre en las habitaciones con vistas a los continentes.",
             "Infografía arquitectónica en el espacio exterior 3D del año 2060 de un 'Resort Orbital de Gravedad Artificial' en forma de rueda toroidal giratoria gigantesca orbitando a 450 km sobre la superficie azul y blanca del planeta Tierra, mostrando una sección de las habitaciones de lujo donde una familia de turistas estelares pasea en gravedad normal gracias a la rotación centrífuga; desde el enorme ventanal panorámico del salón mirador superior, contemplan fascinados el amanecer orbital de la Vía Láctea y el resplandor de la atmósfera terrestre que curva el horizonte cósmico en un espectáculo inolvidable.")

add_fut_item("7.1.13.", "Año 2063: La gran red de trenes de levitación magnética en tubo al vacío (Hyperloop) a 1200 km/h", 
             "El transporte de superficie a velocidad supersónica: túneles subterráneos y viaductos sellados al vacío que conectan Madrid con París o Berlín en menos de dos horas sin fricción del aire ni CO2.",
             "Infografía de ingeniería civil y aerodinámica 3D en el año 2063 de una estación terminal de Hyperloop subterránea de diseño orgánico en mármol blanco y vegetación colgante, mostrando en corte el tubo transparente sellado al vacío en cuyo interior flota magnéticamente sin tocar los rieles una aerodinámica cápsula de pasajeros en acabado plata y cobre brillante; en la plataforma, viajeros con equipajes ligeros acceden al tren supersónico que viaja a 1.200 km/h consumiendo una fracción minúscula de energía solar y sin emitir el menor ruido o vibración.")

add_fut_item("7.1.14.", "Año 2065: Desalinizadoras solares de grafeno y reverdecimiento del Desierto del Sahara", 
             "La victoria definitiva sobre la sequía global: membranas atómicas de grafeno que convierten agua de mar en agua potable a coste casi cero, transportándola por canales solares para crear selvas y vergeles en el desierto.",
             "Infografía ecológica de gran escala y regeneración de ecosistemas 3D en el año 2065 en la costa del norte de África (Sahara), mostrando una monumental planta desalinizadora impulsada por campos solares flotantes en el mar que utiliza membranas de filtración de grafeno a nivel molecular; desde la planta parte un gran río o canal artificial azul turquesa de agua dulce que se adentra por cientos de kilómetros en el desierto antes árido, transformando las dunas de arena naranja en un frondoso valle verde cultivado con millones de palmeras datileras, campos de cereales y arboledas habitadas por aves y comunidades autosuficientes felices.")

add_header_2("7.2. El Futuro Medio: Exploración de Marte, Genética y Mega-Estructuras (2070 - 2150)")
add_fut_item("7.2.1.", "Año 2070: La Primera Ciudad en Marte ('Ares Vallis Capitol') bajo cúpulas de diamante", 
             "La consolidación de una civilización interplanetaria: 50.000 colonos viviendo en paz bajo gigantescas cúpulas geodésicas de diamante sintético en el planeta rojo con parques forestales y gravedad reducida al 38%.",
             "Infografía arquitectónica 3D impresionante y luminosa del año 2070 mostrando el interior de la gran cúpula central de 'Ares Vallis', la primera ciudad capital en Marte, construida con paneles triangulares de diamante sintético ultra-resistente que dejan pasar la luz solar pero bloquean la radiación cósmica; en el interior presurizado de 2 kilómetros de diámetro se extiende un parque urbano arbolado con un lago de agua de deshielo marciano, rodeado por edificios de apartamentos residenciales de terracota roja, mientras en los cielos interiores jóvenes colonos y niños saltan y vuelan en alas delta con enorme agilidad aprovechando que la gravedad marciana es un tercio de la terrestre.")

add_fut_item("7.2.2.", "Año 2075: Ascensores espaciales de nanotubos de carbono anclados en el Ecuador marítimo", 
             "La autopista directa a las estrellas: cables hiper-resistentes de 36.000 km de longitud por los que trepan cápsulas eléctricas de carga pesada desde plataformas en el océano pacífico hasta la órbita geoestacionaria a coste ínfimo.",
             "Infografía espacial de ingeniería monumental en corte 3D del año 2075 de un 'Ascensor Espacial Ecuatorial', mostrando en la parte inferior una gran plataforma flotante del tamaño de una isla artificial en el Océano Pacífico de aguas calmas; desde su centro se eleva hacia el cielo infinito un cable blanco y azul brillante tejido con nanotubos de carbono pura, por el cual trepa a 300 km/h un enorme vagón o cápsula cilíndrica de pasajeros y carga impulsada por rayos láser solares, atravesando las nubes y llegando en la parte superior a una gigantesca estación espacial orbital de contrapeso en órbita geoestacionaria rodeada de naves estelares acopladas.")

add_fut_item("7.2.3.", "Año 2080: La gran red de satélites colectores solares cósmicos que envían energía por microondas", 
             "La energía limpia infinita 24/7: espejos y paneles solares de varios kilómetros en órbita que captan la luz del sol sin interferencia de nubes o noche, enviando un haz de energía inalámbrica a antenas receptoras en los desiertos.",
             "Infografía de astrofísica e ingeniería energética en el año 2080 en órbita alta, mostrando una colosal 'Planta Solar Espacial' formada por una matriz de espejos dorados ultraligeros de 5 kilómetros de diámetro y paneles de captación fotovoltaica que flotan en el vacío cósmico bañados por un sol radiante no nublado nunca; en el centro del enjambre orbital, un emisor de ondas guía un haz láser o microondas seguro de color ámbar luminoso y perfectamente enfocado que desciende a través de la atmósfera terrestre hasta una enorme red de antenas receptoras circulares ('rectenas') en un desierto terrestre, alimentando de luz y calor sin combustibles fósiles a continentes enteros.")

add_fut_item("7.2.4.", "Año 2090: Minería e industrialización automatizada en los asteroides cercanos a la Tierra (Cinturón NEO)", 
             "La obtención de metales nobles sin dañar la Tierra: enjambres de robots autónomos que extraen miles de toneladas de platino, níquel y agua en asteroides metálicos pesados flotando en el vacío del espacio.",
             "Infografía de ingeniería minera espacial 3D en el año 2090 sobre un asteroide metálico del tipo Psique de 10 kilómetros de largo en el cinturón cercano a la Tierra, mostrando cómo una flota de naves refinería automatizadas y rovers mineros robóticos con brazos láser y cortadores de plasma extraen venas relucientes de platino, cobalto y hierro puro bajo una luz solar dura y sin atmósfera; al fondo se aprecia cómo los metales refinados son moldeados in situ por impresoras 3D en gigantescas vigas estructurales destinadas a la construcción de nuevas naves coloniales estelares sin perturbar la ecología terrestre en lo más mínimo.")

add_fut_item("7.2.5.", "Año 2100: El Primer Siglo post-envejecimiento molecular y terapias de senescencia cero", 
             "La revolución de la longevidad biológica: terapias epigenéticas celulares que reprograman el reloj biológico de los tejidos de personas de 90 años otorgándoles la vitalidad, agilidad, salud cardiovascular y lucidez de los 30 años de por vida.",
             "Infografía médica e ilustración humanista emotiva del año 2100 en un centro de 'Epigenética de la Longevidad' frente al mar en una mañana de primavera, mostrando a una familia de cuatro generaciones donde los abuelos de 105 años poseen la complexión atlética, piel tersa, cabello fuerte y agilidad física de jóvenes de 30 años jugando un partido de tenis y riendo en la playa con sus bisnietos; una ventana gráfica lateral explica el mecanismo biológico en 3D donde 'factores de reprogramación celular de Yamanaka controlados por IA' limpian las células senescentes y restauran los telómeros del ADN cerebral y cardíaco al estado óptimo de la juventud perpetua.")

add_fut_item("7.2.6.", "Año 2115: El Inicio de la Terraformación de Marte con espejos orbitales y fábricas de calentamiento", 
             "El despertar verde del planeta rojo: gigantescos espejos solares en órbita marciana concentran luz sobre los casquetes polares para derretir el hielo de agua y CO2, creando una atmósfera densa y las primeras nubes y lluvia en eones.",
             "Infografía de ingeniería planetaria monumental en el año 2115 sobre el Polo Sur del planeta Marte, mostrando una constelación de inmensos espejos orbitales de película de aluminio ultra-fina de 20 kilómetros de ancho inclinados en el espacio, que reflejan y concentran haces de luz solar cálida sobre el casquete helado de agua y dióxido de carbono marciano; en la superficie marciana se forman espectaculares cañones de ríos y lagos de agua de deshielo que fluyen por primera vez en 3.000 millones de años, mientras enormes torres generadoras liberan vapor de agua y gases de efecto invernadero benignos para formar una incipiente atmósfera con nubes blancas y las primeras praderas de musgos adaptados en los valles.")

add_fut_item("7.2.7.", "Año 2130: Interfaz Cerebro-Ordenador no invasiva por ultrasonidos focales y telepatía digital", 
             "La comunicación mental fluida: diademas estéticas de grafeno y ultrasonidos que permiten a los humanos comunicarse entre sí por el pensamiento con imágenes completas y descargar libros o aprender idiomas en segundos mientras duermen.",
             "Infografía neuro-tecnológica 3D de altísima sofisticación ambientada en el año 2130 en una biblioteca universitaria rodeada de naturaleza y jardines zen, mostrando a dos estudiantes sentados frente a frente que llevan puestas unas discretas y elegantes diademas de titanio y grafeno con luces LED cian en las sienes; entre ellos flota en el aire un campo de visualización holográfico neuronal en tiempo real donde comparten, intercambian y editan directamente con el pensamiento complejas ecuaciones tridimensionales de física cuántica y recuerdos visuales de gran nitidez sin pronunciar una sola palabra ni usar teclados, en una sinfonía de inteligencia aumentada y empatía telepática absoluta.")

add_fut_item("7.2.8.", "Año 2150: Ciudades flotantes y aerostáticas en las nubes altas del planeta Venus", 
             "La conquista del cielo venusiano: hábitats esféricos y plataformas flotantes a 50 km de altitud sobre la superficie infernal de Venus, donde la presión y la temperatura son exactamente idénticas a las del clima primaveral terrestre con gravedad 0,9G.",
             "Infografía de exploración planetaria y arquitectura aerostática 3D en el año 2150 en la alta atmósfera de Venus a 50 kilómetros de altitud, mostrando una deslumbrante 'Ciudad Nube de Venus' formada por varios hábitats esféricos de membrana blanca y dorada unidos por puentes colgantes e invernaderos flotantes repletos de vegetación; los hábitats flotan apaciblemente sobre un mar infinito de nubes de color melocotón y oro iluminadas por un sol cercano y radiante, mientras pequeñas aeronaves e hidroaviones eléctricos de exploración conectan las colonias de investigación en un cielo sereno de temperatura templada (25°C) y presión de una atmósfera terrestre.")

add_header_2("7.3. El Futuro Lejano: Colonización Interestelar y Motores de Curvatura (2200 - 3000)")
add_fut_item("7.3.1.", "Año 2200: El Motor de Curvatura ('Alcubierre Warp Drive') y el primer salto a Próxima Centauri", 
             "El viaje más rápido que la luz teórica: naves con anillos de materia exótica que contraen el espaciotiempo por delante y lo expanden por detrás, recorriendo 4,2 años luz en tan solo 4 meses sin violar las leyes de la física relativista.",
             "Infografía de astrofísica cuántica y propulsión estelar en el año 2200 de la primera nave interestelar tripulada 'ISV Explorer One' en ruta hacia la estrella Próxima Centauri (a 4,2 años luz), mostrando un alargado navío espacial blanco rodeado por tres colosales anillos de contención magnética de los que emana un campo de energía de color violeta y cian ('burbuja de curvatura o Warp Drive'); la infografía ilustra en corte 3D geométrico cómo el espaciotiempo de la malla cósmica se comprime visiblemente delante de la proa en ondas azules y se expande o estira detrás en ondas rojas, permitiendo al navío surcar el océano interestelar a velocidad superlumínica aparente con total paz interior en las zonas residenciales de la nave.")

add_fut_item("7.3.2.", "Año 2350: Terra-formación de 'Próxima Centauri b' y biomas bioluminiscentes bajo el sol rojo", 
             "El primer exoplaneta gemelo de la Tierra habitado: cómo la flora cultivada por biólogos humanos adquiere tonos morados, negros y bioluminiscentes para absorber la luz infrarroja del sol enano rojo Próxima Centauri.",
             "Infografía y paisaje natural en el año 2350 en la superficie del exoplaneta 'Próxima Centauri b', mostrando una nueva colonia humana ecologista instalada junto a una tranquila costa marina bajo el cielo de color melocotón donde destaca el enorme disco de un Sol Enano Rojo resplandeciente en el horizonte sin quemar; el bosque circundante, genéticamente diseñado por ecólogos humanos para optimizar la luz infrarroja, exhibe un follaje en tonos violeta oscuro, índigo y ébano salpicado por flores bioluminiscentes que emiten una suave luz verde esmeralda y cian, con colonos paseando sin trajes espaciales respirando el aire puro del primer mundo interestelar colonizado por nuestra especie.")

add_fut_item("7.3.3.", "Año 2500: El Primer Contacto con una civilización extraterrestre pacífica y arqueológica en el cosmos", 
             "El descubrimiento más trascendental de la historia: el encuentro diplomático y científico de la humanidad con los guardianes milenarios de una biblioteca galáctica en las afueras del sistema de Vega.",
             "Infografía y obra artística de corte histórico e diplomático estelar ambientada en el año 2500 en el gran atrio de una estación orbital ancestral descubierta en el sistema estelar de Vega, ilustrando el momento del 'Primer Contacto Universal en Paz': una delegación de científicos, lingüistas y embajadores humanos con trajes ceremoniales blancos sonríen e intercambian un saludo de paz e inteligencia matemática (el teorema de Pitágoras holográfico) con dos seres diplomáticos alienígenas esbeltos, pacíficos y longevos de piel cristalina y vestiduras doradas translúcidas; alrededor de ellos flotan esferas de datos lumínicos con la historia acumulada de millones de años de vida inteligente en la Vía Láctea, celebrando el fin de la soledad cósmica del ser humano.")

add_fut_item("7.3.4.", "Año 2750: Los Grandes Exploradores del Océano Subterráneo de la Luna Europa y sus abismos de calor", 
             "La biología en la oscuridad perpetua: submarinos nucleares autónomos y bionavegantes descubren ciudades hidrotermales y criaturas gigantes fosforescentes en el mar bajo 20 km de hielo de Júpiter.",
             "Infografía oceanográfica y de astrobiología marina 3D en el año 2750 en los abismos oscuros del océano subterráneo del satélite Europa de Júpiter (bajo 20 kilómetros de corteza helada), mostrando un avanzado submarino de exploración biológica en forma de mantarraya transparente con potentes focos LED sumergido a 5.000 metros de profundidad; sus luces revelan un espectacular ecosistema hidrotermal alrededor de chimeneas volcánicas que escupen agua caliente y minerales oro, habitadas por bosques de gusanos de tubo gigantes y gráciles criaturas marinas bioluminiscentes similares a medusas y pulpos fosforescentes en azul y púrpura que nadan pacíficamente en las cálidas corrientes abisales sin haber visto jamás la luz del sol.")

add_fut_item("7.3.5.", "Año 3000: La Red del Milenio y la 'Esfera de Dyson-Swarm' parcial alrededor del Sol", 
             "El hito del milenio (Tipo II de Kardashev): una vasta constelación orbital de millones de satélites colectores que envuelven el ecuador solar capturando el 1% de toda la energía de nuestra estrella natal.",
             "Infografía astrofísica monumental del Año 3000 con el Sistema Solar convertido en una civilización de Tipo II de Kardashev, mostrando un 'Enjambre de Dyson' (Dyson Swarm) en el ecuador del Sol: un cinturón de millones de estaciones espaciales colectoras de energía de diamante y titanio de 10 km cada una orbitando en una danza sincronizada perfecta alrededor del brillante disco solar incandescente; el enjambre capta un uno por ciento de la inmensa producción energética del Sol y la redirige por haces de luz coherente hacia hábitats orbitales, laboratorios de física fundamental y hacia una colosal puerta de salto interestelar ('Stargate') en construcción entre la órbita de Marte y Júpiter preparada para unir de forma instantánea y pacífica los brazos espirales de la Vía Láctea.")

add_header_2("7.4. Más Allá de lo Imaginable: Milenios de Sabiduría Cósmica (Año 5.000 a 1.000.000)")
add_fut_item("7.4.1.", "Año 5.000: Computación cuántica biológica y el gran archivo de la memoria humana en cristales de diamante", 
             "La salvaguarda eterna de nuestra herencia cultural: cómo toda la literatura, música, ciencia y el genoma de cada ser vivo terrestre jamás existido es grabado a nivel atómico dentro de cubos de diamante indestrucibles ocultos en la Luna.",
             "Infografía y fotografía de producto hiperdetallada del año 5.000 en la 'Bóveda del Gran Archivo de la Memoria Humana' en el subsuelo de la Luna, mostrando el interior de una cámara de platino puro y luz dorada en el centro de la cual levita magnéticamente un cubo de diamante sintético transparente y perfecto de 10 centímetros de lado; en el interior del diamante, un láser de femtosegundos ha grabado a nivel molecular en 5D billones de terabytes de información con la historia completa de la especie humana, la música de Bach, las obras del Prado, la literatura de Cervantes y el ADN completo de toda la flora y fauna del planeta Tierra en una cápsula del tiempo eterna y resistente a eones geológicos.")

add_fut_item("7.4.2.", "Año 10.000: La gran terraformación y reanimación de la atmósfera de la Luna Tierra", 
             "El satélite gris convertido en un jardín orbital: el aporte de cometas y generadores gravitacionales permite dotar a la Luna de un cielo azul, nubes, mares poco profundos y bosques de abetos en el lado visible.",
             "Infografía de paisaje espacial en el año 10.000 vista desde la órbita baja terrestre, mostrando una vista sobrecogedora y poética de la Luna totalmente transformada: la cara visible que antes era un desierto de cráteres grises luce ahora un cinturón ecuatorial verde esmeralda cubierto de frondosos bosques templados y lagos azules de agua pura ('Mare Tranquillitatis' convertido en un verdadero mar navegable con veleros), envuelta en una fina atmósfera con nubes blancas y un cielo celeste crepuscular, contrastando con el inmenso globo azul de la Madre Tierra resplandeciendo en el fondo estrellado con el doble de brillo que en la antigüedad.")

add_fut_item("7.4.3.", "Año 25.000: Navegación inter-galáctica por agujeros de gusano estabilizados y puertas cósmicas", 
             "El atajo supremo del universo: anillos hiper-masivos de materia exótica en el espacio profundo que doblan la geometría galáctica conectando la Vía Láctea con la Galaxia de Andrómeda en un paso de 10 segundos.",
             "Infografía de física relativista e ingeniería cósmica 3D en el año 25.000 en el borde exterior del Sistema Solar, mostrando un monumental 'Agujero de Gusano Estabilizado' o Puerta de Salto Interestelar en forma de un gigantesco anillo de oro y titanio de 500 kilómetros de diámetro sostenido por torres estabilizadoras de campo gravitacional; dentro del anillo del portal no se ve el espacio local, sino que se observa con total nitidez el espectacular y deslumbrante núcleo espiral y las estrellas doradas de la Galaxia de Andrómeda (a 2,5 millones de años luz de distancia), a través de la cual un elegante navío explorador humano en forma de gota de luz cruza plácidamente en un viaje intergaláctico instantáneo y pacífico.")

add_fut_item("7.4.4.", "Año 50.000: El Sol artificial portátil para descongelar y colonizar las lunas de los planetas gigantes", 
             "El milagro térmico de los mundos helados: estrellas termonucleares compactas encendidas por ingenieros humanos en órbita alrededor de Titán, Europa y Tritón, derritiendo sus hielos para formar paraísos tropicales en el sistema exterior.",
             "Infografía 3D planetaria e impresionante ambientada en la superficie de la luna Tritón orbitando el planeta gigante Neptuno en el año 50.000, mostrando cómo se ha logrado calentar un mundo helado del sistema solar exterior: en el cielo de color azul índigo oscuro destaca el inmenso y espectacular disco azul zafiro de Neptuno con sus anillos inclinados, acompañado justo al lado por un 'Sol de Fusión Artificial' (una estrella termo-eléctrica de encendido humano de 10 kilómetros) que baña con luz dorada y calor primaveral la superficie de la luna, convirtiendo lo que antes era hielo de nitrógeno en un hermoso lago alpino de agua cristalina rodeado de praderas verdes alpinas y cabañas de madera de colonos estelares.")

add_fut_item("7.4.7.", "Año 100.000: Humanidad estelar y diversificación genética adaptada a mil gravedades en el cosmos", 
             "La evolución dirigida con sabiduría: cómo las diferentes colonias humanas distribuidas por 10.000 mundos de la Vía Láctea han adaptado fisiológicamente sus cuerpos y sentidos para vivir en mundos de alta gravedad, planetas acuáticos y gravedad cero en perfecta fraternidad biológica.",
             "Infografía científica y humanista 3D del año 100.000 ambientada en el gran salón de congresos de la Academia Galáctica en una estación espacial neutral, ilustrando la pacífica y diversa evolución biológica de la especie humana en el cosmos a través de un grupo de embajadores inter-estelares conversando y sonriendo en un círculo de luz: a la izquierda, ciudadanos de planetas de súper-gravedad (2G) con complexión atlética robusta y huesos reforzados que irradian fuerza; en el centro, los clásicos terrestres de 1G con trajes elegantes en seda; y a la derecha, los gráciles habitantes de colonias orbitales de gravedad cero de 2,5 metros de altura con extremidades largas y estilizadas flotando en el aire como bailarines, todos unidos por el mismo lenguaje, empatía y respeto ancestral a su origen común en el planeta Tierra.")

add_fut_item("7.4.8.", "Año 250.000: La reforestación y conversión del planeta Tierra en Santuario Cósmico Protegido", 
             "El regreso de la Madre Tierra a su estado virginal: tras el traslado de toda la industria pesada y minería al espacio exterior, nuestro planeta natal es declarado 'Parque Nacional Universal' sin contaminación, donde crecen bosques milenarios y las especies extintas son clonadas y devueltas a la libertad.",
             "Infografía ecologista 3D conmovedora y majestuosa de la superficie del planeta Tierra en el año 250.000 convertida oficialmente en el 'Santuario Biológico Sagrado de la Vía Láctea', mostrando una vista aérea de un frondoso e infinito bosque subtropical virgen en Europa central cruzado por un río prístino y caudaloso donde no hay rascacielos ni carreteras de cemento, sino manadas de mamuts lanudos clonados y ciervos paseando libres en paz por las riberas entre secuoyas gigantescas; en el cielo despejado, muy por encima de las nubes, se aprecia discretamente un anillo orbital de observación flotando en silencio desde donde millones de peregrinos humanos y estelares contemplan con reverencia el Edén natural intacto que fue la cuna originaria de su especie hace un cuarto de millón de años.")

add_fut_item("7.4.9.", "Año 500.000: Computación y ciudades eternas alrededor de agujeros negros (Cilindros de Penrose)", 
             "La obtención de energía infinita de la gravedad: cómo las civilizaciones galácticas construyen ciudades orbitales super-densas alrededor de agujeros negros giratorios (Proceso de Penrose) para obtener cantidades incalculables de energía limpia del propio espaciotiempo curvo.",
             "Infografía astrofísica 3D sobrecogedora y de alta tecnología en el año 500.000 alrededor de un agujero negro supermasivo giratorio (tipo Gargantúa de Interstellar) en el centro de un cúmulo estelar, mostrando el brillante disco de acreción de gas incandescente color oro y naranja curvado por la inmensa gravedad y el círculo negro absoluto del horizonte de sucesos; en una órbita segura y estable por encima del disco revolotean miles de gigantescas estaciones colectoras de energía de diamante y titanio que lanzan y recogen haces de radiación electromagnética utilizando el 'Proceso de Penrose' para extraer energía inagotable de la rotación del espaciotiempo, enviando billones de teravatios por láseres de largo alcance a mundos habitados en las afueras seguras de la galaxia.")

add_fut_item("7.4.10.", "Año 1.000.000: El Gran Futuro Cósmico: La Humanidad como los Guardianes Eternos de la Luz y la Vida", 
             "El horizon de un millón de años en el futuro: nuestra especie se ha transformado en los jardineros compasivos del universo y custodios de la vida inteligente, viajando por las galaxias para encender soles apagados, proteger mundos nacientes y celebrar el triunfo del amor, la memoria y la conciencia en el tiempo infinito.",
             "Infografía y obra de arte 3D monumental, poética y trascendental que ilustra a la Humanidad en el Año 1.000.000 de nuestra era cósmica como los 'Guardianes de la Luz en la Vía Láctea', mostrando una vista panorámica del bullicioso núcleo galáctico donde miles de estrellas y nebulosas de colores rosa, oro y azul profundo resplandecen en el firmamento infinito; en primer plano sobre la terraza de un templo estelar de cristal flotando en el vacío del espacio, una figura anciana y sabia de rostro sereno e iluminado por un aura de luz dorada, vestida con túnicas blancas atemporales, levanta sus manos con ternura junto a un niño explorador para liberar en el espacio un enjambre de pequeñas esferas resplandecientes de luz y vida que vuelan hacia un nuevo sistema planetario en formación, simbolizando que el conocimiento, la bondad y la herencia cultural transmitidas de generación en generación en la Tierra y en el curso de mayores pervivirán eternamente para iluminar el cosmos por siempre.")

add_fut_item("7.4.11.", "Año 10.000 (II): La Reforestación Completa y Selvas Tropicales en Marte", 
             "El florecimiento definitivo del planeta rojo: tras milenios de terraformación continua, Marte luce como una segunda Tierra con densas selvas ecuatoriales, ríos caudalosos en Valles Marineris y mares templados en el norte poblados por fauna y colonos en paz.",
             "Infografía 3D y paisaje natural en el planeta Marte en el año 10.000 tras milenios de terraformación pacífica, mostrando el espectacular cañón de Valles Marineris cubierto de una exuberante selva tropical húmeda con altas cascadas de agua fresca que caen por acantilados rojizos hasta un río caudaloso en el fondo del valle; en el cielo azul despejado con nubes blancas vuelan aves tropicales y pequeñas aeronaves turísticas silenciosas, mientras en una terraza panorámica al borde del abismo un grupo de alumnos y profesores de astronomía contemplan maravillados la belleza del que fuera el planeta desértico rojo ahora convertido en un paraíso biológico vibrante.")

add_fut_item("7.4.12.", "Año 50.000 (II): Acueductos Cósmicos y Transporte de Hielo del Cinturón de Kuiper", 
             "La gran red de abastecimiento hídrico interestelar: enormes convoyes espaciales automatizados que capturan cometas y bloques de agua pura en el Cinturón de Kuiper y los transportan mediante rutas gravitacionales para fertilizar mundos áridos nacientes.",
             "Infografía espacial y de ingeniería de transporte cósmico 3D en el año 50.000 en las afueras del Sistema Solar (Cinturón de Kuiper), mostrando un monumental 'Convoy Acueducto Interestelar' formado por una nave remolcadora de plasma guiando a un gigantesco cometa de hielo de agua pura de 50 kilómetros de diámetro cubierto por una malla de contención magnética azulada; de fondo resplandecen campos de estrellas e infinidad de planetas enanos mientras el convoy avanza suavemente por una autopista de luz láser para llevar agua fresca y vida a un nuevo sistema solar en proceso de terraformación a varios años luz de distancia.")

add_fut_item("7.4.13.", "Año 150.000: Conexión Simpática y Biosferas Autoconscientes en Exoplanetas", 
             "La armonía superior de la inteligencia y la ecología: cómo colonias humanas milenarias se integran en perfecta simbiosis bio-psíquica con los bosques y redes nerviosas naturales de árboles de mundos lejanos, viviendo en equilibrio telepático y pacífico.",
             "Infografía humanista y biológica 3D en el año 150.000 en un exoplaneta boscoso del brazo galáctico de Sagitario, mostrando un santuario natural donde árboles gigantescos con hojas en tonos cobre y plata se conectan subterráneamente por una red de raíces luminosas color cian que actúan como el sistema nervioso central del planeta; sentados en círculo bajo el árbol madre en un prado de musgo suave, ancianos sabios de la colonia estelar se toman de las manos en un ritual de meditación y contemplación pacífica mientras hebras de luz suave conectan sus mentes con la naturaleza viviente en perfecta simbiosis y bienestar.")

add_fut_item("7.4.14.", "Año 300.000: Arcas Estelares de Conservación Biológica e Historia Universal", 
             "Los grandes museos vivientes navegando por las galaxias: naves arca colosales de 50 km de longitud que albergan en su interior copias exactas y ecosistemas intactos de la pradera africana, el Amazonas y los bosques de abetos terrestres navegando hacia Andrómeda.",
             "Infografía 3D monumental de una 'Nave Arca de Conservación Estelar' navegando por el espacio profundo entre la Vía Láctea y Andrómeda en el año 300.000, mostrando una nave geodésica transparente dividida en enormes biomas o compartimentos ecológicos cilíndricos de 10 kilómetros cada uno: en un cilindro se aprecia una réplica exacta de la sabana africana con elefantes y jirafas caminando al sol artificial, en el contiguo se ve un frondoso bosque lluvioso amazónico y en otro un bosque de abetos nevados alpinos; la nave viaja en silencio por el vacío como un santuario eterno y museo viviente de la herencia biológica del planeta Tierra salvaguardado por la humanidad por los siglos de los siglos.")

add_fut_item("7.4.15.", "Año 750.000: Arquitectura de Luz Cristalina y Esferas Celestiales en Nebulosas", 
             "El arte arquitectónico sublime de casi un millón de años en el futuro: ciudades y santuarios construidos en el corazón de nebulosas estelares utilizando luz cristalizada y campos de fuerza sólidos en lugar de piedra y metal, flotando en nubes de polvo estelar rosado y oro.",
             "Infografía artística 3D y sublime del año 750.000 en el centro de la Nebulosa de Orión, mostrando una etérea e imponente ciudad cósmica flotante construida íntegramente con 'Arquitectura de Luz Cristalina' y campos de fuerza translúcidos que brillan en tonos nácar, diamante y zafiro; los edificios tienen formas de espirales elegantes, cúpulas abiertas y puentes de luz flotantes sobre mares de polvo interestelar color rosa y violeta donde nacen nuevas estrellas resplandecientes, habitada por seres humanos longevos y pacíficos que dedican su vida eterna al arte, la música universal y la exploración del misterio de la creación.")

add_fut_item("7.4.16.", "Año 900.000: El Gran Reencuentro de las Ramas Humanas en el Núcleo Galáctico", 
             "La celebración inter-galáctica de la fraternidad: el congreso donde delegaciones de millones de mundos humanos dispersos por la Vía Láctea se reúnen en paz para compartir su historia, sus aprendizajes y su gratitud en una gran fiesta estelar de luz y música.",
             "Infografía 3D emotiva y festiva en el año 900.000 en una gigantesca plaza cívica orbital en el núcleo de la Vía Láctea iluminada por miles de soles dorados cercanos, mostrando la 'Celebración del Gran Reencuentro Humano': delegaciones de exploradores y ciudadanos llegados de millones de mundos lejanos, vistiendo trajes culturales diversos desde túnicas luminosas hasta capas de seda estelar, se abrazan con alegría, ríen y comparten proyecciones holográficas de sus respectivos planetas y creaciones artísticas en una atmósfera de amor fraternal absoluto, demostrando que a pesar de las distancias y los eones de tiempo, el corazón y la compasión humana siguen siendo el verdadero motor del universo.")

