add_header_1("VIII. EL REINO DE LA NATURALEZA Y BIODIVERSIDAD (CATÁLOGO [NAT] — 60 SESIONES)")

add_header_2("8.1. Mamíferos en Acción, Flores del Mundo y Grandes Momentos Salvajes")
add_nat_item("8.1.1.", "El Caballo Salvaje y su Biomecánica de Galope (Infografía Científica V2)", 
             "La pureza y potencia del galope libre de un caballo de pelaje blanco rompiendo el agua a toda velocidad mientras el sol despunta en el horizonte.", 
             'ROL Y TAREA\nActúa como un Ilustrador de Enciclopedia Científica de clase mundial y Arquitecto de Grafos de Conocimiento.\nTu tarea es generar un “Infográfico de Enciclopedia Científica Ilustrada Universal” altamente detallado, extremadamente intrincado y visualmente impactante, en un estilo clásico de enciclopedia científica sin marca (SIN logos, SIN firmas, SIN marcas de agua), con acabado de pieza de colección editorial de lujo.\n\nCALIDAD, RESOLUCIÓN Y CANDADO ANTI-MARCAS DE AGUA (Máxima Prioridad)\nResolución ultra alta, calidad 8K / Full HD, nitidez absoluta en TODA la imagen. Cada módulo, diagrama, línea guía y texto debe verse enfocado y definido, no solo el retrato central. Cero desenfoque (blur), cero pixelado, cero ruido digital ni artefactos de compresión, cero bordes borrosos o mal definidos. Líneas de grabado limpias en cualquier tamaño. Renderizado con calidad de impresión editorial de lujo (tipo lámina de museo o portada de National Geographic), lista para imprimir en gran formato sin perder detalle.\nPROHIBICIÓN ESTRICTA DE MARCAS DE AGUA Y STOCK (CERO WATERMARKS): La ilustración debe estar COMPLETAMENTE LIMPIA de marcas de agua, sin texto de bancos de imágenes (CERO texto \'iStock\', \'Getty Images\', \'Shutterstock\', sin símbolos de copyright © ni marcas diagonales translúcidas). No añadir firmas inventadas ni logotipos comerciales en ninguna parte del pergamino.\n\nBLOQUEO TOTAL DE IDIOMA Y ANATOMÍA HUMANA\n1. IDIOMA: TODO el texto visible debe estar en ESPAÑOL correcto, sin excepción: el título superior del encabezado, el pie de página / cintillo inferior, los títulos de los 8 módulos, cada etiqueta, cada leyenda de diagrama, cada palabra dentro de las ilustraciones internas, y la línea de tiempo inferior. No debe aparecer NINGUNA palabra en inglés en ningún rincón de la imagen. Todas las palabras deben estar bien escritas, sin errores ortográficos.\n2. PRECISIÓN BIOLÓGICA ESTRICTA (CERO ANATOMÍA HUMANA): Todos los diagramas de órganos, pulmones, músculos, ojos, patas, alas o cráneos ilustrados en los 8 recuadros deben ser ESTRICTAMENTE los del sujeto animal o vegetal tratado (El Caballo Salvaje). BAJO NINGÚN CONCEPTO se deben dibujar pulmones humanos, corazones humanos, manos o extremidades humanas ni diagramas médicos antropomórficos. Si se ilustra el sistema respiratorio, óseo o circulatorio, debe mostrar única y rigurosamente la morfología biológica específica de esta especie.\n\nDATOS DEL SUJETO A ILUSTRAR\n- Tipo de Sujeto: ANIMAL / MAMÍFERO EQUINO DE VELOCIDAD\n- Nombre del Sujeto: El Caballo Salvaje\n- Nombre Científico / Específico: Equus ferus\n\nESTILO VISUAL CORE\nIlustración científica fina y extremadamente detallada, renderizada en altísima resolución y máxima nitidez, sobre un fondo de pergamino/papel retro envejecido, en tonos beige, crema y sepia dorado. Trazos delicados a tinta con técnica de grabado clásico (cross-hatching / grabado en talla dulce), perfectamente definidos y sin desenfoque, con una estética de diario de campo naturalista vintage de altísima calidad editorial. Inspirado en las láminas de historia natural de los siglos XVIII-XIX (estilo Ernst Haeckel / Audubon / Maria Sibylla Merian / Georges Cuvier), estructurado como un grafo de conocimiento académico moderno. Papel con textura visible de fibra, ligeras manchas de humedad y foxing en los bordes, y un sutil viñeteado oscuro en las esquinas para dar profundidad y carácter de reliquia auténtica. Intrincadamente complejo, compuesto de forma profesional y con acabado de lujo editorial.\n\nCONSISTENCIA Y CALIDAD VISUAL UNIFORME\nTodos los diagramas e ilustraciones de los 8 módulos deben tener EXACTAMENTE el mismo nivel de detalle, nitidez y acabado artesanal que una lámina de grabado científico del siglo XIX; nunca debe verse como iconos planos, clip-art digital, dibujos vectoriales simplificados, ni verse borrosos o de menor resolución que el retrato central. Cada esquema anatómico, botánico o físico debe estar sombreado con cross-hatching fino, nítido y consistente, con la misma paleta sepia/tinta en toda la pieza, de modo que el conjunto se sienta como una sola lámina de atlas antiguo grabada por un mismo artista en alta resolución, no como iconos sueltos, borrosos o de baja calidad pegados alrededor del retrato central. Evitar por completo estilo caricaturesco, plano, tipo sticker o infografía moderna de baja resolución.\n\nARQUITECTURA Y COMPOSICIÓN ESPACIAL DE LA LÁMINA\n1. FIGURA CENTRAL DE ACCIÓN ("POP-OUT" 3D): Ubicar en el centro visual de la lámina la siguiente escena de acción dramática y dinámica del sujeto: "La pureza y potencia del galope libre de un caballo de pelaje blanco rompiendo el agua a toda velocidad mientras el sol despunta en el horizonte.". Esta figura o escena central debe estar renderizada en hiperrealismo fotográfico, estilo 3D y calidad 8K con el máximo nivel de detalle y dinamismo (agua salpicando, músculos en tensión, polvo, nieve, rocío o plumas en movimiento con nitidez absoluta), dando la sensación de romper físicamente el plano de la ilustración plana (efecto “pop-out” tridimensional) frente al arte 2D de enciclopedia del fondo. Incluir una sombra proyectada realista sobre el pergamino y un sutil resplandor dorado alrededor de la figura o escena central para reforzar el contraste dramático entre lo 3D fotorrealista en movimiento y el grabado 2D antiguo.\n2. BLOQUE DE ENCABEZADO Y TÍTULO: Directamente encima de la figura central de acción, colocar el título "EL CABALLO SALVAJE" en tipografía serif grande, elegante, nítida y en negrita (estilo clásico tipo Didot o Garamond). Debajo, el nombre científico o formal "Equus ferus" en cursiva itálica. Incluir un subtítulo descriptivo corto y poético en español: "La pureza y potencia del galope libre de un caballo de pelaje blanco rompiendo el agua a toda velocidad mientras el sol despunta en el horizonte.".\n3. LOS 8 MÓDULOS PERIFÉRICOS DE CONOCIMIENTO (GRAFO CIENTÍFICO): Distribuir alrededor de la escena central de acción exactamente 8 recuadros o módulos ilustrados en grabado cross-hatching fino, conectados con el centro mediante finas líneas guía y flechas con leyendas en español. Los 8 módulos son:\n   - Módulo 1: Anatomía Ósea del Galope Equino (Esquema del esqueleto del equino —CERO ANATOMÍA HUMANA— mostrando cómo la columna y extremidades actúan como un sistema de palancas para propulsión en cuatro tiempos).\n   - Módulo 2: El Casco Equino y Amortiguación Hidráulica (Corte del casco equino y la almohadilla plantar que absorbe impactos de 1 tonelada de fuerza al galopar).\n   - Módulo 3: Respiración Acoplada al Tranco (Esquema torácico de caballo showing cómo el movimiento del pistón intestinal contra el diafragma empuja los pulmones equinos 1 vez por zancada).\n   - Módulo 4: Musculatura Glútea y Cuartos Traseros (Corte anatómico muscular del equino responsable de la aceleración explosiva y salto por encima del agua de marisma).\n   - Módulo 5: Visión Lateral Panorámica 350° (Anatomía ocular del caballo con pupilas horizontales que le permiten vigilar el horizonte sin puntos ciegos laterales).\n   - Módulo 6: Termorregulación por SudorACIÓN Equina (Esquema fisiológico de las glándulas sudoríparas del equino y cómo el pelaje blanco refleja la radiación solar).\n   - Módulo 7: Dinámica de Fluidos al Salpicar Agua (Física de las ondas hidrocinéticas y dispersión de gotas generadas por el impacto del casco en marisma acuática).\n   - Módulo 8: Evolución del Pie Equino (Eohippus a Equus) (Cronología fósil en grabado mostrando la reducción evolutiva de 5 dedos hasta un único dedo central blindado).\n4. LÍNEA DE TIEMPO / CRONOLOGÍA INFERIOR: En el cintillo horizontal inferior, integrar una línea de tiempo o cronología evolutiva bellamente grabada con 4 fases: "1. Suspensión Aérea (0 s): Las 4 patas en el aire sin tocar la marisma", "2. Impacto Trasero (0.2 s): Pata trasera izquierda absorbe el peso y propulsa", "3. Apoyo Diagonal (0.4 s): Pata trasera derecha y delantera izquierda en tierra", "4. Impulso Delantero (0.6 s): Pata delantera derecha proyecta el salto hacia adelante". Todo perfectamente legible en español.\n5. MARCO Y PIE DE PÁGINA DE COLECCIÓN: Enmarcar la lámina con un filo de grabado en cobre clásico y añadir en el borde inferior un sello o recuadro cartográfico que indique: "LÁMINA CIENTÍFICA UNIVERSAL — COLECCIÓN DE BIODIVERSIDAD ÉPOCA DORADA", junto con una escala técnica de proporción y firma del ilustrador naturalista.', 
             tips="👉 Reto Práctico: Consulta Científica Empoderada — Pide directamente a tu inteligencia artificial que te explique en profundidad y con palabras sencillas: ¿Por qué los veterinarios dicen que el caballo respira exactamente una vez por cada tranco o zancada al galopar, y cómo funciona el 'pistón intestinal' que empuja sus pulmones como un fuelle mecánico?")
add_nat_item("8.1.2.", "Biomecánica de Impacto del Carnero Cimarron (Infografía Científica V2)", 
             "El momento cumbre de la berrea alpina: dos carneros gigantes colisionando sus enormes cuernos en espiral con un estruendo de alta montaña.", 
             'ROL Y TAREA\nActúa como un Ilustrador de Enciclopedia Científica de clase mundial y Arquitecto de Grafos de Conocimiento.\nTu tarea es generar un “Infográfico de Enciclopedia Científica Ilustrada Universal” altamente detallado, extremadamente intrincado y visualmente impactante, en un estilo clásico de enciclopedia científica sin marca (SIN logos, SIN firmas, SIN marcas de agua), con acabado de pieza de colección editorial de lujo.\n\nCALIDAD, RESOLUCIÓN Y CANDADO ANTI-MARCAS DE AGUA (Máxima Prioridad)\nResolución ultra alta, calidad 8K / Full HD, nitidez absoluta en TODA la imagen. Cada módulo, diagrama, línea guía y texto debe verse enfocado y definido, no solo el retrato central. Cero desenfoque (blur), cero pixelado, cero ruido digital ni artefactos de compresión, cero bordes borrosos o mal definidos. Líneas de grabado limpias en cualquier tamaño. Renderizado con calidad de impresión editorial de lujo (tipo lámina de museo o portada de National Geographic), lista para imprimir en gran formato sin perder detalle.\nPROHIBICIÓN ESTRICTA DE MARCAS DE AGUA Y STOCK (CERO WATERMARKS): La ilustración debe estar COMPLETAMENTE LIMPIA de marcas de agua, sin texto de bancos de imágenes (CERO texto \'iStock\', \'Getty Images\', \'Shutterstock\', sin símbolos de copyright © ni marcas diagonales translúcidas). No añadir firmas inventadas ni logotipos comerciales en ninguna parte del pergamino.\n\nBLOQUEO TOTAL DE IDIOMA Y ANATOMÍA HUMANA\n1. IDIOMA: TODO el texto visible debe estar en ESPAÑOL correcto, sin excepción: el título superior del encabezado, el pie de página / cintillo inferior, los títulos de los 8 módulos, cada etiqueta, cada leyenda de diagrama, cada palabra dentro de las ilustraciones internas, y la línea de tiempo inferior. No debe aparecer NINGUNA palabra en inglés en ningún rincón de la imagen. Todas las palabras deben estar bien escritas, sin errores ortográficos.\n2. PRECISIÓN BIOLÓGICA ESTRICTA (CERO ANATOMÍA HUMANA): Todos los diagramas de órganos, pulmones, músculos, ojos, patas, alas o cráneos ilustrados en los 8 recuadros deben ser ESTRICTAMENTE los del sujeto animal o vegetal tratado (El Carnero Cimarrón). BAJO NINGÚN CONCEPTO se deben dibujar pulmones humanos, corazones humanos, manos o extremidades humanas ni diagramas médicos antropomórficos. Si se ilustra el sistema respiratorio, óseo o circulatorio, debe mostrar única y rigurosamente la morfología biológica específica de esta especie.\n\nDATOS DEL SUJETO A ILUSTRAR\n- Tipo de Sujeto: ANIMAL / MAMÍFERO ALPINO DE COMBATE\n- Nombre del Sujeto: El Carnero Cimarrón\n- Nombre Científico / Específico: Ovis canadensis\n\nESTILO VISUAL CORE\nIlustración científica fina y extremadamente detallada, renderizada en altísima resolución y máxima nitidez, sobre un fondo de pergamino/papel retro envejecido, en tonos beige, crema y sepia dorado. Trazos delicados a tinta con técnica de grabado clásico (cross-hatching / grabado en talla dulce), perfectamente definidos y sin desenfoque, con una estética de diario de campo naturalista vintage de altísima calidad editorial. Inspirado en las láminas de historia natural de los siglos XVIII-XIX (estilo Ernst Haeckel / Audubon / Maria Sibylla Merian / Georges Cuvier), estructurado como un grafo de conocimiento académico moderno. Papel con textura visible de fibra, ligeras manchas de humedad y foxing en los bordes, y un sutil viñeteado oscuro en las esquinas para dar profundidad y carácter de reliquia auténtica. Intrincadamente complejo, compuesto de forma profesional y con acabado de lujo editorial.\n\nCONSISTENCIA Y CALIDAD VISUAL UNIFORME\nTodos los diagramas e ilustraciones de los 8 módulos deben tener EXACTAMENTE el mismo nivel de detalle, nitidez y acabado artesanal que una lámina de grabado científico del siglo XIX; nunca debe verse como iconos planos, clip-art digital, dibujos vectoriales simplificados, ni verse borrosos o de menor resolución que el retrato central. Cada esquema anatómico, botánico o físico debe estar sombreado con cross-hatching fino, nítido y consistente, con la misma paleta sepia/tinta en toda la pieza, de modo que el conjunto se sienta como una sola lámina de atlas antiguo grabada por un mismo artista en alta resolución, no como iconos sueltos, borrosos o de baja calidad pegados alrededor del retrato central. Evitar por completo estilo caricaturesco, plano, tipo sticker o infografía moderna de baja resolución.\n\nARQUITECTURA Y COMPOSICIÓN ESPACIAL DE LA LÁMINA\n1. FIGURA CENTRAL DE ACCIÓN ("POP-OUT" 3D): Ubicar en el centro visual de la lámina la siguiente escena de acción dramática y dinámica del sujeto: "El momento cumbre de la berrea alpina: dos carneros gigantes colisionando sus enormes cuernos en espiral con un estruendo de alta montaña.". Esta figura o escena central debe estar renderizada en hiperrealismo fotográfico, estilo 3D y calidad 8K con el máximo nivel de detalle y dinamismo (agua salpicando, músculos en tensión, polvo, nieve, rocío o plumas en movimiento con nitidez absoluta), dando la sensación de romper físicamente el plano de la ilustración plana (efecto “pop-out” tridimensional) frente al arte 2D de enciclopedia del fondo. Incluir una sombra proyectada realista sobre el pergamino y un sutil resplandor dorado alrededor de la figura o escena central para reforzar el contraste dramático entre lo 3D fotorrealista en movimiento y el grabado 2D antiguo.\n2. BLOQUE DE ENCABEZADO Y TÍTULO: Directamente encima de la figura central de acción, colocar el título "EL CARNERO CIMARRÓN" en tipografía serif grande, elegante, nítida y en negrita (estilo clásico tipo Didot o Garamond). Debajo, el nombre científico o formal "Ovis canadensis" en cursiva itálica. Incluir un subtítulo descriptivo corto y poético en español: "El momento cumbre de la berrea alpina: dos carneros gigantes colisionando sus enormes cuernos en espiral con un estruendo de alta montaña.".\n3. LOS 8 MÓDULOS PERIFÉRICOS DE CONOCIMIENTO (GRAFO CIENTÍFICO): Distribuir alrededor de la escena central de acción exactamente 8 recuadros o módulos ilustrados en grabado cross-hatching fino, conectados con el centro mediante finas líneas guía y flechas con leyendas en español. Los 8 módulos son:\n   - Módulo 1: Cuernos en Espiral de Queratina y Hueso (Corte óseo de los cuernos de carnero de 14 kg mostrando el núcleo óseo alveolar y revestimiento de queratina que crece toda su vida).\n   - Módulo 2: Cráneo con Amortiguadores Alveolares de Aire (Esquema craneal estrictamente ovino —CERO ANATOMÍA HUMANA— mostrando cámaras óseas huecas y puntales que absorben impactos de 60 G).\n   - Módulo 3: Protección Cerebrovascular en el Choque (Esquema circulatorio cerebral del carnero que previene conmociones cerebrales y desgarros arteriales al chocar a 40 km/h).\n   - Módulo 4: Musculatura Cervical de Halterofilia (Corte de los tendones y músculos hipertrofiados del cuello del carnero que estabilizan la cabeza en el milisegundo de colisión).\n   - Módulo 5: Pezuñas Bipartidas y Almohadilla Antideslizante (Anatomía de la pezuña en pinza con borde exterior duro de queratina e interior de goma elástica para agarre en roca vertical).\n   - Módulo 6: Pulmones y Corazón de Alta Montaña (Diagrama torácico de carnero con adaptación a hipoxia en altitudes mayores a 4.000 metros de la Sierra Madre).\n   - Módulo 7: Física del Choque Balístico (Gráfico vectorial de fuerzas que demuestra cómo la energía cinética de 3.400 julios se disipa por la espiral del cuerno sin partir el cuello).\n   - Módulo 8: Jerarquía y Selección Sexual (Esquema de las crestas anuales de crecimiento en el cuerno que marcan la edad y dominancia del macho rey).\n4. LÍNEA DE TIEMPO / CRONOLOGÍA INFERIOR: En el cintillo horizontal inferior, integrar una línea de tiempo o cronología evolutiva bellamente grabada con 4 fases: "1. Aceleración Frontal: Los dos machos corren a 40 km/h sobre el risco", "2. Elevación a Dos Patas: Proyección del peso corporal hacia adelante", "3. Impacto Alveolar (0 milisegundos): Colisión de 60 G absorbida por el cráneo", "4. Disipación y Equilibrio: Los cuernos vibran dispersando la fuerza acústica". Todo perfectamente legible en español.\n5. MARCO Y PIE DE PÁGINA DE COLECCIÓN: Enmarcar la lámina con un filo de grabado en cobre clásico y añadir en el borde inferior un sello o recuadro cartográfico que indique: "LÁMINA CIENTÍFICA UNIVERSAL — COLECCIÓN DE BIODIVERSIDAD ÉPOCA DORADA", junto con una escala técnica de proporción y firma del ilustrador naturalista.', 
             tips='👉 Reto Práctico: Consulta Científica Empoderada — Pide directamente a tu inteligencia artificial que te explique en profundidad y con palabras sencillas: ¿Cómo es posible que los carneros de las montañas choquen sus cabezas a 40 kilómetros por hora sufriendo un impacto de 60 G sin fracturarse el cráneo ni sufrir una conmoción cerebral grave?')
